insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e5000000-0000-0000-0000-000000000001', 'ukmla', '2539b4e6-1650-44f6-b84d-38d0ca534b8b',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e5000000-0000-0000-0000-000000000001', 'A', 'Arrange outpatient respiratory clinic review in 2 weeks and continue her current inhalers', false, 'Ruled out because this is an acute severe attack needing immediate emergency department treatment, not deferred outpatient review.', 1),
('e5000000-0000-0000-0000-000000000001', 'B', 'Give high-flow oxygen to maintain SpO2 94-98%, nebulised salbutamol and ipratropium bromide (back-to-back if needed), and oral prednisolone 40mg', true, 'Correct. This presentation (PEFR 33-50% predicted, RR>25, HR>110, inability to complete sentences) meets criteria for acute severe asthma; the priority is oxygen, repeated/back-to-back nebulised bronchodilators (salbutamol plus ipratropium) plus systemic corticosteroids given immediately.', 2),
('e5000000-0000-0000-0000-000000000001', 'C', 'Discharge with a course of oral antibiotics for a presumed chest infection', false, 'Ruled out because there is no evidence of infection here; treating a severe asthma attack with antibiotics does not address bronchospasm and delays essential therapy.', 3),
('e5000000-0000-0000-0000-000000000001', 'D', 'Perform an arterial blood gas and withhold treatment until the result is available', false, 'Ruled out because bronchodilator and steroid treatment should not be delayed pending an ABG; treatment starts immediately alongside investigations.', 4),
('e5000000-0000-0000-0000-000000000001', 'E', 'Sedate her and proceed straight to intubation given her tachypnoea', false, 'Ruled out because intubation is reserved for life-threatening/exhausted patients failing maximal medical therapy, not first-line for a severe (not life-threatening) attack.', 5),
('e5000000-0000-0000-0000-000000000002', 'A', 'Continue 15L/min oxygen via non-rebreathe mask to maximise his SpO2', false, 'Ruled out because uncontrolled high-flow oxygen in a CO2 retainer worsens hypercapnia and can precipitate respiratory failure and coma.', 1),
('e5000000-0000-0000-0000-000000000002', 'B', 'Stop all oxygen therapy immediately given the risk of hypercapnia', false, 'Ruled out because he remains hypoxic (SpO2 82% on air) and needs oxygen, just carefully titrated rather than withdrawn.', 2),
('e5000000-0000-0000-0000-000000000002', 'C', 'Administer IV naloxone for suspected opioid-induced respiratory depression', false, 'Ruled out because there is no opioid history; his drowsiness and flap are consistent with CO2 narcosis, not opioid toxicity.', 3),
('e5000000-0000-0000-0000-000000000002', 'D', 'Switch to titrated oxygen via a Venturi mask targeting SpO2 88-92% and reassess with a repeat ABG', true, 'Correct. He has features of CO2 narcosis from over-oxygenation superimposed on likely chronic hypercapnia (compensated by a raised bicarbonate); COPD patients at risk of type 2 respiratory failure should have oxygen titrated to a target saturation of 88-92%, with early reassessment.', 4),
('e5000000-0000-0000-0000-000000000002', 'E', 'Proceed immediately to intubation and mechanical ventilation without a trial of controlled oxygen or NIV', false, 'Ruled out because first-line management is controlled oxygen with consideration of non-invasive ventilation if he remains acidotic and hypercapnic; invasive ventilation is reserved for NIV failure or contraindication.', 5),
('e5000000-0000-0000-0000-000000000003', 'A', 'Reassure him that a silent chest with a normal PaCO2 is a reassuring sign that his bronchospasm is resolving', false, 'Ruled out and dangerous; a silent chest reflects severe airflow limitation, not resolution, and a normal PaCO2 in this context (he should be hyperventilating) suggests fatigue and impending respiratory failure.', 1),
('e5000000-0000-0000-0000-000000000003', 'B', 'Discharge him home once his SpO2 improves above 94% with a salbutamol inhaler', false, 'Ruled out because life-threatening features mandate admission and senior review, not discharge based on a single improved observation.', 2),
('e5000000-0000-0000-0000-000000000003', 'C', 'Give a single dose of nebulised salbutamol only and reassess in 4 hours', false, 'Ruled out because this underestimates severity; life-threatening asthma needs continuous or back-to-back nebulisers and urgent senior input, not a single dose with delayed reassessment.', 3),
('e5000000-0000-0000-0000-000000000003', 'D', 'Arrange outpatient spirometry to confirm the diagnosis before escalating treatment', false, 'Ruled out because spirometry is inappropriate and unsafe during an acute severe or life-threatening attack; management must not be delayed for diagnostic confirmation.', 4),
('e5000000-0000-0000-0000-000000000003', 'E', 'Call for urgent senior anaesthetic/ICU review for probable impending respiratory arrest, while continuing maximal medical therapy (oxygen, nebulised bronchodilators, IV steroids, consider IV magnesium)', true, 'Correct. Silent chest, exhaustion, and a normal/rising PaCO2 in an acute asthma attack are life-threatening features indicating imminent respiratory failure; immediate senior and critical care involvement is required alongside continued maximal medical therapy, as he may need intubation.', 5),
('e5000000-0000-0000-0000-000000000004', 'A', 'Add an inhaled corticosteroid to form triple therapy (LABA/LAMA/ICS)', true, 'Correct. Guidance recommends escalating to triple inhaled therapy (LABA plus LAMA plus ICS) in patients with COPD who continue to exacerbate on LABA/LAMA, particularly when blood eosinophils are raised (≥300 cells/microL), as this predicts a good response to inhaled corticosteroids in reducing exacerbation frequency.', 1),
('e5000000-0000-0000-0000-000000000004', 'B', 'Stop the LAMA component and add an inhaled corticosteroid alone with the LABA', false, 'Ruled out because this removes an effective bronchodilator; the correct escalation is to add ICS to the existing LABA/LAMA (triple therapy), not substitute one component.', 2),
('e5000000-0000-0000-0000-000000000004', 'C', 'Start long-term oral corticosteroids to reduce exacerbation frequency', false, 'Ruled out because long-term oral steroids carry significant systemic side effects and are not recommended for routine COPD maintenance; inhaled triple therapy is preferred.', 3),
('e5000000-0000-0000-0000-000000000004', 'D', 'Start prophylactic oral antibiotics (e.g., azithromycin) as first-line before considering triple inhaled therapy', false, 'Ruled out because prophylactic macrolides are considered after optimising inhaled therapy (including triple therapy) in patients who continue to exacerbate, not as the first escalation step.', 4),
('e5000000-0000-0000-0000-000000000004', 'E', 'Reassure him that no further escalation is possible and continue his current therapy unchanged', false, 'Ruled out because triple therapy escalation is an appropriate next step for a patient exacerbating on LABA/LAMA with raised eosinophils.', 5),
('e5000000-0000-0000-0000-000000000005', 'A', 'Start long-term high-dose inhaled corticosteroids as the mainstay of treatment', false, 'Ruled out because ICS is not the mainstay of bronchiectasis management (which is not primarily an eosinophilic or asthmatic process); airway clearance and treating infection are central.', 1),
('e5000000-0000-0000-0000-000000000005', 'B', 'Arrange immediate surgical lobectomy of the affected lobes', false, 'Ruled out because surgery is reserved for localised, severe, or complicated disease unresponsive to medical management, not first-line for bilateral disease.', 2),
('e5000000-0000-0000-0000-000000000005', 'C', 'Refer for chest physiotherapy (airway clearance techniques) and give sputum culture-guided antibiotics for exacerbations', true, 'Correct. This presentation (chronic productive cough, recurrent infections, HRCT showing bronchial dilatation) is classic for bronchiectasis; core management is regular airway clearance physiotherapy to reduce sputum burden and exacerbation frequency, with prompt sputum-culture-directed antibiotics for exacerbations.', 3),
('e5000000-0000-0000-0000-000000000005', 'D', 'Reassure her that this is likely a self-limiting post-infectious cough requiring no specific action', false, 'Ruled out because her presentation and CT findings confirm bronchiectasis, an important chronic condition needing active management, not reassurance alone.', 4),
('e5000000-0000-0000-0000-000000000005', 'E', 'Start oral corticosteroids for presumed eosinophilic airway inflammation', false, 'Ruled out because there is no indication of an eosinophilic or asthmatic driver here; steroids are not first-line therapy for bronchiectasis.', 5),
('e5000000-0000-0000-0000-000000000006', 'A', 'Start a regular low-dose inhaled corticosteroid preventer inhaler', true, 'Correct. Frequent SABA use (needing more than one inhaler a month) and night-time symptoms indicate poorly controlled asthma; guidance recommends starting a regular low-dose inhaled corticosteroid (or an ICS/formoterol maintenance-and-reliever regimen) rather than continuing SABA-only treatment, which is associated with increased risk of exacerbations and mortality.', 1),
('e5000000-0000-0000-0000-000000000006', 'B', 'Continue his reliance on salbutamol as required and review again in 12 months', false, 'Ruled out because this level of SABA overuse and night symptoms signals poor control requiring escalation now, not continued monotherapy with delayed review.', 2),
('e5000000-0000-0000-0000-000000000006', 'C', 'Prescribe a long-acting muscarinic antagonist (LAMA) alone as the next step', false, 'Ruled out because a LAMA is not the standard next step in asthma management; an inhaled corticosteroid is the appropriate preventer therapy at this stage.', 3),
('e5000000-0000-0000-0000-000000000006', 'D', 'Refer for immediate hospital admission given his frequent inhaler use', false, 'Ruled out because he is stable with no admission-level features described; this is an outpatient step-up in preventer therapy, not an emergency.', 4),
('e5000000-0000-0000-0000-000000000006', 'E', 'Start a course of oral prednisolone and stop his salbutamol inhaler completely', false, 'Ruled out because oral steroids are for exacerbations, not routine step-up therapy, and stopping the reliever inhaler entirely would leave him without rescue treatment.', 5),
('e5000000-0000-0000-0000-000000000007', 'A', 'Prescribe ambulatory oxygen for use only during exercise, with no assessment for continuous LTOT', false, 'Ruled out because his resting hypoxaemia meets criteria for LTOT assessment (continuous use for at least 15 hours a day), not ambulatory-only oxygen.', 1),
('e5000000-0000-0000-0000-000000000007', 'B', 'Refer for assessment for long-term oxygen therapy (LTOT)', true, 'Correct. Two stable resting ABGs showing a PaO2 <7.3 kPa (or <8 kPa with evidence of cor pulmonale or polycythaemia) meet the criteria for assessment for long-term oxygen therapy, which has been shown to improve survival in hypoxaemic COPD patients.', 2),
('e5000000-0000-0000-0000-000000000007', 'C', 'Reassure him that oxygen therapy is not indicated until he develops peripheral oedema', false, 'Ruled out because LTOT criteria are met by a PaO2 <7.3 kPa alone on two stable measurements, without needing to wait for cor pulmonale to develop.', 3),
('e5000000-0000-0000-0000-000000000007', 'D', 'Start home non-invasive ventilation instead of oxygen therapy, as this is the definitive treatment for chronic hypoxaemia', false, 'Ruled out because NIV is indicated for chronic hypercapnic respiratory failure, not simply for hypoxaemia; his presentation here is hypoxaemia and would first need LTOT assessment.', 4),
('e5000000-0000-0000-0000-000000000007', 'E', 'Advise that he must continue smoking cessation for a further 12 months before LTOT can be considered', false, 'Ruled out because although continued smoking is a contraindication to home oxygen due to fire risk, he has already stopped smoking 6 months ago and further delay is not required before assessment.', 5),
('e5000000-0000-0000-0000-000000000008', 'A', 'Hypersensitivity pneumonitis', false, 'Ruled out because this typically shows upper/mid-zone predominant ground-glass change and mosaic attenuation with a relevant antigen exposure history, not a basal UIP pattern with honeycombing.', 1),
('e5000000-0000-0000-0000-000000000008', 'B', 'Chronic obstructive pulmonary disease', false, 'Ruled out because spirometry here shows a restrictive, not obstructive, pattern, and the clinical and radiological findings are not consistent with COPD.', 2),
('e5000000-0000-0000-0000-000000000008', 'C', 'Sarcoidosis', false, 'Ruled out because sarcoidosis typically causes upper/mid-zone changes with bilateral hilar lymphadenopathy, not a basal UIP pattern with honeycombing.', 3),
('e5000000-0000-0000-0000-000000000008', 'D', 'Idiopathic pulmonary fibrosis', true, 'Correct. Progressive breathlessness with a dry cough, bibasal fine crackles, clubbing, restrictive spirometry, and an HRCT showing a usual interstitial pneumonia (UIP) pattern (subpleural/basal reticulation, honeycombing, traction bronchiectasis, no significant ground-glass) in an older patient with no identified cause is classic for idiopathic pulmonary fibrosis.', 4),
('e5000000-0000-0000-0000-000000000008', 'E', 'Left ventricular heart failure', false, 'Ruled out because although breathlessness and crackles can occur in heart failure, the chronic progressive course, restrictive spirometry, and characteristic UIP pattern on HRCT point to a primary interstitial lung disease rather than cardiac failure.', 5),
('e5000000-0000-0000-0000-000000000009', 'A', 'Start long-term antibiotics for a presumed atypical chest infection', false, 'Ruled out because the intermittent, exposure-related symptom pattern and HRCT findings point to an immune-mediated hypersensitivity reaction, not an infective process requiring antibiotics.', 1),
('e5000000-0000-0000-0000-000000000009', 'B', 'Commence high-dose inhaled corticosteroids without addressing the antigen exposure', false, 'Ruled out because corticosteroids do not replace antigen avoidance, which is essential to prevent ongoing lung damage; continued exposure will perpetuate disease regardless of steroid use.', 2),
('e5000000-0000-0000-0000-000000000009', 'C', 'Advise complete avoidance of the causative antigen (removal of the birds from the home)', true, $x$Correct. This history (symptomatic improvement away from home, exposure to avian antigens, HRCT showing ground-glass and mosaic attenuation) is characteristic of hypersensitivity pneumonitis (bird fancier's lung); the single most important intervention is identifying and completely avoiding further antigen exposure, as continued exposure risks progression to irreversible fibrosis.$x$, 3),
('e5000000-0000-0000-0000-000000000009', 'D', 'Reassure her that this is a normal ageing change and no action is needed', false, 'Ruled out because this is an important, potentially progressive environmental lung disease requiring active intervention, not reassurance.', 4),
('e5000000-0000-0000-0000-000000000009', 'E', 'Refer for immediate lung transplantation assessment', false, 'Ruled out because transplantation is reserved for end-stage fibrotic disease unresponsive to conservative measures; this is premature before antigen avoidance and monitoring.', 5),
('e5000000-0000-0000-0000-000000000010', 'A', 'Pulmonary tuberculosis', false, 'Ruled out because TB typically presents with constitutional symptoms (fever, night sweats, weight loss), productive cough, and often unilateral or apical changes rather than this acute erythema nodosum and bilateral hilar lymphadenopathy syndrome.', 1),
('e5000000-0000-0000-0000-000000000010', 'B', 'Lymphoma', false, 'Ruled out because although lymphoma can cause hilar lymphadenopathy, the acute triad of erythema nodosum, arthralgia, and bilateral hilar nodes together with hypercalcaemia is far more consistent with sarcoidosis.', 2),
('e5000000-0000-0000-0000-000000000010', 'C', 'Community-acquired pneumonia', false, 'Ruled out because there are no features of an acute infective pneumonia (consolidation, purulent sputum, fever) and the chest X-ray shows clear lung fields with hilar lymphadenopathy, not consolidation.', 3),
('e5000000-0000-0000-0000-000000000010', 'D', 'Rheumatoid arthritis', false, 'Ruled out because although joint symptoms are present, RA does not explain the erythema nodosum, bilateral hilar lymphadenopathy, or hypercalcaemia; this constellation is characteristic of sarcoidosis.', 4),
('e5000000-0000-0000-0000-000000000010', 'E', 'Sarcoidosis (Löfgren syndrome)', true, 'Correct. The combination of erythema nodosum, bilateral hilar lymphadenopathy, arthralgia, and hypercalcaemia in a young woman is classic for Löfgren syndrome, an acute presentation of sarcoidosis that typically has an excellent prognosis with frequent spontaneous resolution.', 5),
('e5000000-0000-0000-0000-000000000011', 'A', 'Stop amiodarone (in discussion with cardiology) and refer for respiratory assessment including HRCT', true, 'Correct. Progressive dyspnoea, dry cough, and bilateral interstitial infiltrates in a patient on long-term amiodarone raise strong suspicion of amiodarone-induced pulmonary toxicity; the key management step is prompt discontinuation of the causative drug (in conjunction with the prescribing specialist) alongside respiratory work-up, as continued exposure risks progressive, potentially irreversible fibrosis.', 1),
('e5000000-0000-0000-0000-000000000011', 'B', 'Continue amiodarone and start empirical antibiotics for a presumed chest infection', false, 'Ruled out because there are no infective features (fever, purulent sputum) described, and continuing a likely causative drug would allow ongoing lung injury.', 2),
('e5000000-0000-0000-0000-000000000011', 'C', 'Increase the amiodarone dose to improve rhythm control and reassess breathlessness separately', false, 'Ruled out because this would worsen a probable drug-induced pneumonitis; the priority is to address the suspected cause, not increase exposure.', 3),
('e5000000-0000-0000-0000-000000000011', 'D', 'Reassure him that amiodarone has no recognised pulmonary side effects', false, 'Ruled out because amiodarone is a well-recognised cause of pulmonary toxicity, including interstitial pneumonitis and fibrosis, particularly with prolonged use.', 4),
('e5000000-0000-0000-0000-000000000011', 'E', 'Arrange elective cardioversion before considering any respiratory investigations', false, 'Ruled out because this does not address the suspected drug-induced lung disease and delays necessary respiratory assessment.', 5),
('e5000000-0000-0000-0000-000000000012', 'A', 'Community-acquired pneumonia', false, 'Ruled out because the recurrent, exposure-related pattern with rapid resolution away from the trigger is not typical of bacterial pneumonia, which would not recur in this cyclical fashion tied to hay exposure.', 1),
('e5000000-0000-0000-0000-000000000012', 'B', $x$Acute hypersensitivity pneumonitis (farmer's lung)$x$, true, $x$Correct. Recurrent episodes of fever, breathlessness, and cough occurring several hours after exposure to mouldy hay (containing thermophilic actinomycete antigens), with resolution on removal from exposure, is the classic presentation of acute hypersensitivity pneumonitis (farmer's lung).$x$, 2),
('e5000000-0000-0000-0000-000000000012', 'C', 'Occupational asthma', false, 'Ruled out because occupational asthma causes bronchospasm and wheeze with reversible airflow obstruction rather than fever, myalgia, and diffuse micronodular shadowing on chest X-ray.', 3),
('e5000000-0000-0000-0000-000000000012', 'D', 'Pulmonary tuberculosis', false, 'Ruled out because TB presents with a more chronic, progressive course with constitutional symptoms, not acute self-limiting episodes tightly linked to a specific exposure.', 4),
('e5000000-0000-0000-0000-000000000012', 'E', 'Legionella pneumonia', false, 'Ruled out because Legionella is associated with exposure to contaminated water sources (e.g., air conditioning, hot tubs), not mouldy hay, and would not typically show this recurrent exposure-related pattern.', 5),
('e5000000-0000-0000-0000-000000000013', 'A', $x$Pulmonary embolism secondary to Raynaud's phenomenon$x$, false, $x$Ruled out because Raynaud's phenomenon does not cause pulmonary embolism, and the chronic progressive course with restrictive PFTs is not consistent with an embolic event.$x$, 1),
('e5000000-0000-0000-0000-000000000013', 'B', 'Simple deconditioning due to reduced exercise tolerance', false, 'Ruled out because the objective findings of bibasal crackles and abnormal pulmonary function tests indicate a genuine parenchymal lung process, not simple deconditioning.', 2),
('e5000000-0000-0000-0000-000000000013', 'C', 'Community-acquired pneumonia', false, 'Ruled out because there is no acute infective picture (fever, purulent sputum, acute onset); the chronic progressive course points to an underlying interstitial process related to her systemic sclerosis.', 3),
('e5000000-0000-0000-0000-000000000013', 'D', 'Pulmonary oedema secondary to left ventricular failure', false, 'Ruled out because although pulmonary hypertension can complicate systemic sclerosis, the described findings (chronic progressive dyspnoea, bibasal crackles, restrictive PFTs with reduced DLCO) are characteristic of ILD rather than acute cardiac failure.', 4),
('e5000000-0000-0000-0000-000000000013', 'E', 'Systemic sclerosis-associated interstitial lung disease', true, 'Correct. Interstitial lung disease is a recognised and important complication of systemic sclerosis, presenting with progressive dyspnoea, dry cough, bibasal crackles, and a restrictive pattern with disproportionately reduced DLCO on pulmonary function testing; it is a leading cause of mortality in systemic sclerosis.', 5),
('e5000000-0000-0000-0000-000000000014', 'A', 'Mesothelioma', false, 'Ruled out because mesothelioma typically presents with chest pain and a unilateral pleural effusion or pleural thickening rather than the bilateral lower zone reticular parenchymal shadowing described here, though both are asbestos-related and can coexist.', 1),
('e5000000-0000-0000-0000-000000000014', 'B', 'Silicosis', false, 'Ruled out because silicosis is caused by inhalation of crystalline silica dust (e.g., in mining or quarrying), typically causing upper zone nodular shadowing, not the asbestos exposure history and pleural plaques described here.', 2),
('e5000000-0000-0000-0000-000000000014', 'C', 'Idiopathic pulmonary fibrosis', false, 'Ruled out because although the clinical and radiological picture can overlap with IPF, the clear history of significant asbestos exposure with pleural plaques points to asbestosis as the specific diagnosis, not an idiopathic process.', 3),
('e5000000-0000-0000-0000-000000000014', 'D', 'Asbestosis', true, 'Correct. A long latency period after significant occupational asbestos exposure, progressive breathlessness, bibasal fine crackles, clubbing, and a chest X-ray showing lower zone reticular shadowing with pleural plaques is characteristic of asbestosis, a form of pneumoconiosis caused by asbestos fibre inhalation.', 4),
('e5000000-0000-0000-0000-000000000014', 'E', $x$Coal worker's pneumoconiosis$x$, false, 'Ruled out because this results from coal dust inhalation, not asbestos, and does not typically produce pleural plaques.', 5),
('e5000000-0000-0000-0000-000000000015', 'A', 'Reassure him that a normal chest X-ray excludes lung cancer and no further action is needed', false, 'Ruled out because a normal chest X-ray does not reliably exclude lung cancer, particularly with persistent red-flag symptoms and a significant smoking history; further imaging is required.', 1),
('e5000000-0000-0000-0000-000000000015', 'B', 'Start empirical antibiotics for a presumed chest infection and review in 6 weeks', false, 'Ruled out because this delays appropriate cancer investigation in a high-risk patient with red-flag symptoms; urgent further imaging should not be deferred behind an empirical antibiotic trial.', 2),
('e5000000-0000-0000-0000-000000000015', 'C', 'Refer urgently for a contrast-enhanced CT chest despite the normal chest X-ray', true, 'Correct. In a patient over 40 with unexplained persistent cough, weight loss, and a significant smoking history, an urgent referral for further imaging (CT chest) is warranted even with a normal chest X-ray, as chest X-ray has limited sensitivity for early lung cancer; guidance recommends urgent direct-access CT chest for such red-flag presentations.', 3),
('e5000000-0000-0000-0000-000000000015', 'D', 'Arrange a routine (non-urgent) outpatient respiratory clinic referral', false, 'Ruled out because these red-flag features (age, smoking history, persistent cough, weight loss) warrant an urgent pathway, not routine referral.', 4),
('e5000000-0000-0000-0000-000000000015', 'E', 'Repeat the chest X-ray in 3 months to assess for interval change', false, 'Ruled out because given the red-flag features, urgent CT imaging should proceed now rather than waiting for a repeat plain film.', 5),
('e5000000-0000-0000-0000-000000000016', 'A', 'Excessive sodium loss due to diuretic-induced dehydration', false, 'Ruled out because no diuretic use is mentioned, and the clinical picture (euvolaemic, concentrated urine) is not consistent with volume-depleted diuretic-induced hyponatraemia.', 1),
('e5000000-0000-0000-0000-000000000016', 'B', 'Primary adrenal insufficiency causing salt-wasting', false, 'Ruled out because adrenal insufficiency typically causes hypovolaemic hyponatraemia with hyperkalaemia, not the euvolaemic picture described, and is not the classic paraneoplastic association with small cell lung cancer.', 2),
('e5000000-0000-0000-0000-000000000016', 'C', 'Ectopic secretion of antidiuretic hormone from the tumour causing SIADH', true, 'Correct. Small cell lung cancer is strongly associated with paraneoplastic ectopic ADH secretion causing the syndrome of inappropriate antidiuretic hormone secretion (SIADH), producing euvolaemic hyponatraemia with concentrated urine relative to plasma, as seen here.', 3),
('e5000000-0000-0000-0000-000000000016', 'D', 'Hypothyroidism causing water retention', false, 'Ruled out because thyroid function is stated as normal, excluding this as the cause.', 4),
('e5000000-0000-0000-0000-000000000016', 'E', $x$Excess ACTH secretion causing Cushing's syndrome$x$, false, $x$Ruled out because although ectopic ACTH is also a recognised small cell lung cancer paraneoplastic phenomenon, it causes hypokalaemia and features of Cushing's syndrome, not this euvolaemic hyponatraemic picture.$x$, 5),
('e5000000-0000-0000-0000-000000000017', 'A', 'Superior vena cava obstruction', true, 'Correct. Facial and periorbital swelling, distended neck veins, and dilated chest wall collateral veins, worsened by lying flat, in a patient with a known bronchial carcinoma is characteristic of superior vena cava obstruction due to extrinsic tumour compression or invasion of the SVC.', 1),
('e5000000-0000-0000-0000-000000000017', 'B', 'Right heart failure', false, 'Ruled out because right heart failure typically causes peripheral (dependent) oedema and a raised JVP without the characteristic distribution of facial/periorbital swelling and chest wall venous collaterals seen with SVC obstruction.', 2),
('e5000000-0000-0000-0000-000000000017', 'C', 'Pericardial tamponade', false, $x$Ruled out because tamponade classically presents with hypotension, raised JVP, and muffled heart sounds (Beck's triad), not facial swelling with chest wall venous collaterals.$x$, 3),
('e5000000-0000-0000-0000-000000000017', 'D', 'Bilateral pulmonary emboli', false, 'Ruled out because PE typically presents with acute breathlessness, pleuritic chest pain and hypoxia, not facial/periorbital swelling with distended neck and chest wall veins.', 4),
('e5000000-0000-0000-0000-000000000017', 'E', 'Anaphylaxis', false, 'Ruled out because there is no history of an allergen trigger, urticaria, or acute hypotension; the chronic, progressive, positional pattern here fits SVC obstruction, not an acute allergic reaction.', 5),
('e5000000-0000-0000-0000-000000000018', 'A', 'Cervical disc prolapse', false, $x$Ruled out because this would not explain the Horner's syndrome (ptosis, miosis, anhidrosis), which requires sympathetic chain involvement not caused by disc disease.$x$, 1),
('e5000000-0000-0000-0000-000000000018', 'B', $x$An apical (Pancoast) lung tumour causing Horner's syndrome and brachial plexus involvement$x$, true, $x$Correct. This combination of shoulder/arm pain, small hand muscle wasting (lower brachial plexus/C8-T1 involvement), and Horner's syndrome (ptosis, miosis, anhidrosis) in a heavy smoker is classic for a Pancoast tumour, an apical lung cancer invading the brachial plexus and sympathetic chain.$x$, 2),
('e5000000-0000-0000-0000-000000000018', 'C', 'Rotator cuff tear', false, $x$Ruled out because a rotator cuff tear causes shoulder pain and weakness on specific movements but does not cause Horner's syndrome or hand muscle wasting from brachial plexus involvement.$x$, 3),
('e5000000-0000-0000-0000-000000000018', 'D', 'Thoracic outlet syndrome due to a cervical rib', false, $x$Ruled out because although thoracic outlet syndrome can cause arm symptoms, it does not typically cause Horner's syndrome, and the strong smoking history and combination of features here point to malignancy.$x$, 4),
('e5000000-0000-0000-0000-000000000018', 'E', 'Multiple sclerosis', false, $x$Ruled out because MS can cause a variety of neurological signs but does not produce this specific combination of localised brachial plexus signs with ipsilateral Horner's syndrome in this clinical context.$x$, 5),
('e5000000-0000-0000-0000-000000000019', 'A', 'Primary hyperparathyroidism', false, 'Ruled out because primary hyperparathyroidism causes hypercalcaemia with a raised (not suppressed) PTH level, which is inconsistent with the low PTH described here.', 1),
('e5000000-0000-0000-0000-000000000019', 'B', 'Excessive vitamin D intake', false, 'Ruled out because there is no history of vitamin D supplementation, and this would not explain the association with his known squamous cell lung cancer.', 2),
('e5000000-0000-0000-0000-000000000019', 'C', 'Bony metastases causing local osteolysis as the sole mechanism', false, 'Ruled out because although bony metastases can contribute to hypercalcaemia in some cancers, the classic and most common mechanism in squamous cell lung cancer is humoral hypercalcaemia via PTHrP secretion, consistent with the suppressed PTH.', 3),
('e5000000-0000-0000-0000-000000000019', 'D', 'Tumour secretion of parathyroid hormone-related protein (PTHrP)', true, 'Correct. Squamous cell lung carcinoma is classically associated with paraneoplastic hypercalcaemia due to tumour secretion of PTHrP, which mimics PTH action on bone and kidney, causing hypercalcaemia with an appropriately suppressed (low) native PTH level.', 4),
('e5000000-0000-0000-0000-000000000019', 'E', 'Multiple myeloma-related hypercalcaemia', false, 'Ruled out because there is no evidence provided of myeloma (e.g., renal failure, anaemia, bone lesions, paraproteinaemia); the known diagnosis is squamous cell lung cancer, and PTHrP-mediated hypercalcaemia is the classic mechanism here.', 5),
('e5000000-0000-0000-0000-000000000020', 'A', 'Reassure her that incidental nodules found on chest X-ray are always benign and require no follow-up', false, 'Ruled out because an incidental pulmonary nodule cannot be presumed benign without further characterisation; this approach risks missing an early lung cancer.', 1),
('e5000000-0000-0000-0000-000000000020', 'B', 'Proceed directly to surgical excision of the nodule without further imaging or risk assessment', false, 'Ruled out because this is premature; further imaging and risk stratification should be performed first to determine the most appropriate next step, which may be surveillance rather than surgery.', 2),
('e5000000-0000-0000-0000-000000000020', 'C', 'Start empirical anti-tuberculous therapy given the possibility of a tuberculous granuloma', false, 'Ruled out because this assumes a specific diagnosis without appropriate investigation; further imaging (and possibly biopsy) is needed before considering any specific treatment.', 3),
('e5000000-0000-0000-0000-000000000020', 'D', 'Repeat the chest X-ray in 2 years to assess for change', false, 'Ruled out because a nodule of this size warrants more timely and detailed evaluation with CT, not a prolonged interval on plain film alone.', 4),
('e5000000-0000-0000-0000-000000000020', 'E', 'Arrange a CT chest to further characterise the nodule', true, 'Correct. An incidental solitary pulmonary nodule of 8mm or more with no prior imaging for comparison requires further characterisation with CT chest to assess size, morphology, and growth, with risk stratification to guide further management such as PET-CT or biopsy versus surveillance.', 5),
('e5000000-0000-0000-0000-000000000021', 'A', 'Empyema', false, 'Ruled out because empyema typically presents with an acute infective picture (fever, systemic illness) and purulent, not typically bloodstained, pleural fluid, rather than this chronic asbestos-related presentation.', 1),
('e5000000-0000-0000-0000-000000000021', 'B', 'Pulmonary embolism with haemorrhagic infarction', false, 'Ruled out because although PE can cause pleuritic pain and occasionally a blood-stained effusion, the chronic progressive course over months with a clear asbestos exposure history and pleural thickening points to mesothelioma rather than an acute embolic event.', 2),
('e5000000-0000-0000-0000-000000000021', 'C', 'Tuberculous pleural effusion', false, 'Ruled out because TB effusions are typically lymphocyte-predominant exudates and are associated with constitutional symptoms and relevant epidemiological risk factors, not specifically a long-latency asbestos exposure history.', 3),
('e5000000-0000-0000-0000-000000000021', 'D', 'Mesothelioma', true, 'Correct. A long latency after significant asbestos exposure, progressive pleuritic chest pain, breathlessness, and a bloodstained pleural effusion with pleural thickening is characteristic of mesothelioma, an asbestos-related malignancy of the pleura.', 4),
('e5000000-0000-0000-0000-000000000021', 'E', 'Rheumatoid pleural effusion', false, 'Ruled out because there is no history of rheumatoid arthritis or other connective tissue disease; the strong asbestos exposure history and clinical/radiological findings point to mesothelioma.', 5),
('e5000000-0000-0000-0000-000000000022', 'A', 'Arrange an urgent portable chest X-ray to confirm the diagnosis before intervening', false, 'Ruled out because tension pneumothorax is a clinical diagnosis and must be treated immediately; waiting for imaging risks cardiac arrest from obstructive shock.', 1),
('e5000000-0000-0000-0000-000000000022', 'B', 'Give IV fluids and observe, as the hypotension is likely due to blood loss alone', false, 'Ruled out because although haemorrhage should also be addressed, the specific signs described (absent breath sounds, tracheal deviation, distended neck veins) indicate a tension pneumothorax requiring immediate decompression, not fluids alone.', 2),
('e5000000-0000-0000-0000-000000000022', 'C', 'Immediate needle decompression of the right chest (or immediate finger thoracostomy) followed by chest drain insertion, without waiting for a chest X-ray', true, 'Correct. This presentation (absent breath sounds, hyper-resonance, tracheal deviation away from the affected side, distended neck veins, and hypotension) indicates a tension pneumothorax, a clinical diagnosis requiring immediate needle decompression or finger thoracostomy without delay for imaging, as this is immediately life-threatening.', 3),
('e5000000-0000-0000-0000-000000000022', 'D', 'Perform endotracheal intubation as the first priority before addressing the chest findings', false, 'Ruled out because decompressing the tension pneumothorax takes priority, as positive-pressure ventilation before decompression can rapidly worsen the tension physiology and precipitate cardiac arrest.', 4),
('e5000000-0000-0000-0000-000000000022', 'E', 'Insert a formal chest drain in the fifth intercostal space as the first step, without prior needle or finger decompression', false, 'Ruled out because in a peri-arrest tension pneumothorax, immediate needle decompression or finger thoracostomy should not be delayed while preparing for formal chest drain insertion.', 5),
('e5000000-0000-0000-0000-000000000023', 'A', 'Immediate insertion of a large-bore surgical chest drain regardless of symptoms', false, 'Ruled out because immediate chest drain insertion is not required in a stable, minimally symptomatic patient; conservative management, or needle aspiration if intervention is needed for breathlessness, would be tried first.', 1),
('e5000000-0000-0000-0000-000000000023', 'B', 'Discharge immediately with no follow-up arranged', false, 'Ruled out because even with conservative management, follow-up (clinical review and repeat imaging) should be arranged to ensure resolution.', 2),
('e5000000-0000-0000-0000-000000000023', 'C', 'Perform emergency needle decompression as for a tension pneumothorax', false, 'Ruled out because there are no signs of tension pneumothorax (haemodynamic instability, tracheal deviation); this is a stable simple pneumothorax not requiring emergency decompression.', 3),
('e5000000-0000-0000-0000-000000000023', 'D', 'Arrange immediate video-assisted thoracoscopic surgery (VATS) pleurodesis', false, 'Ruled out because surgical pleurodesis is reserved for recurrent pneumothoraces or those requiring intervention that fails initial conservative or aspiration measures, not for a first, stable, minimally symptomatic episode.', 4),
('e5000000-0000-0000-0000-000000000023', 'E', 'Conservative management with consideration of oxygen and outpatient review, given he is minimally symptomatic', true, 'Correct. Current guidance for primary spontaneous pneumothorax favours conservative management in stable, minimally symptomatic patients regardless of size, reserving intervention (needle aspiration or chest drain) for those with significant breathlessness or high-risk features.', 5),
('e5000000-0000-0000-0000-000000000024', 'A', 'Insert an intercostal chest drain, given his significant breathlessness and underlying lung disease', true, 'Correct. In secondary pneumothorax (underlying lung disease such as COPD), guidelines recommend chest drain insertion for patients who are significantly breathless and/or have a pneumothorax rim of 2cm or more, as these patients tolerate pneumothorax poorly and have higher failure rates with simple aspiration.', 1),
('e5000000-0000-0000-0000-000000000024', 'B', 'Manage conservatively with oxygen alone and outpatient review, as for a primary pneumothorax', false, 'Ruled out because secondary pneumothorax with significant breathlessness and a large rim of air in a patient with underlying lung disease requires active drainage, not conservative management alone.', 2),
('e5000000-0000-0000-0000-000000000024', 'C', 'Perform needle aspiration only, without proceeding to chest drain if this fails', false, 'Ruled out because needle aspiration for secondary pneumothorax is generally reserved for minimally symptomatic patients with a smaller rim; here, with significant breathlessness and a rim of 2cm or more, a chest drain is the appropriate first step.', 3),
('e5000000-0000-0000-0000-000000000024', 'D', 'Discharge home with safety-netting advice and no active intervention', false, 'Ruled out because this patient has significant symptoms and a large secondary pneumothorax, both features indicating a need for admission and drainage, not discharge.', 4),
('e5000000-0000-0000-0000-000000000024', 'E', 'Arrange elective outpatient VATS pleurodesis without acute drainage', false, 'Ruled out because this delays urgently needed drainage of a symptomatic pneumothorax; acute management (chest drain) is required first.', 5),
('e5000000-0000-0000-0000-000000000025', 'A', 'Transudate, because the pleural fluid protein is below 40 g/L', false, $x$Ruled out because an absolute pleural fluid protein cut-off alone is a less reliable guide than Light's criteria, and applying Light's criteria properly to the paired serum/pleural values here classifies this as an exudate.$x$, 1),
('e5000000-0000-0000-0000-000000000025', 'B', 'Exudate, because the pleural fluid to serum LDH ratio exceeds 0.6', true, $x$Correct. Light's criteria classify an effusion as exudative if any of: pleural fluid to serum protein ratio >0.5, pleural fluid to serum LDH ratio >0.6, or pleural fluid LDH above the upper limit of normal for serum. Here the LDH ratio is 250/190, approximately 1.3 (>0.6), so this is an exudate by more than one criterion.$x$, 2),
('e5000000-0000-0000-0000-000000000025', 'C', 'Transudate, because the LDH values are both within the normal serum reference range', false, $x$Ruled out because Light's criteria depend on the pleural to serum LDH ratio and its relation to the upper limit of normal, not simply whether the individual values look 'normal'; the ratio here (greater than 0.6) meets exudate criteria.$x$, 3),
('e5000000-0000-0000-0000-000000000025', 'D', 'Indeterminate, requiring pleural biopsy before any classification can be made', false, $x$Ruled out because Light's criteria can be applied directly from the paired serum and pleural fluid values provided; biopsy is not required simply to classify transudate versus exudate.$x$, 4),
('e5000000-0000-0000-0000-000000000025', 'E', 'Exudate, based on pleural fluid appearance alone without needing biochemical criteria', false, $x$Ruled out because classification should be based on Light's biochemical criteria (protein and LDH ratios), not visual appearance of the fluid alone.$x$, 5),
('e5000000-0000-0000-0000-000000000026', 'A', 'Continue the same intravenous antibiotics alone and reassess in 48 hours without draining the effusion', false, 'Ruled out because frank pus in the pleural space (empyema) requires drainage; antibiotics alone are frequently inadequate to clear an established empyema.', 1),
('e5000000-0000-0000-0000-000000000026', 'B', 'Switch to oral antibiotics and discharge for outpatient follow-up', false, 'Ruled out because this patient has a complicated parapneumonic effusion (empyema) requiring inpatient management with drainage, not discharge on oral therapy.', 2),
('e5000000-0000-0000-0000-000000000026', 'C', 'Insert an intercostal chest drain for pleural fluid drainage, in addition to continuing antibiotics', true, 'Correct. Frankly purulent, foul-smelling pleural fluid with a low pH confirms an empyema; management requires prompt tube thoracostomy (chest drain) to drain the infected pleural space, alongside continued appropriate antibiotics, as antibiotics alone are unlikely to resolve a loculated purulent collection.', 3),
('e5000000-0000-0000-0000-000000000026', 'D', 'Perform therapeutic thoracentesis to remove as much fluid as possible in one sitting, then stop antibiotics', false, 'Ruled out because a single aspiration is inadequate for an empyema (which reaccumulates and often loculates); a chest drain is needed, and antibiotics should be continued, not stopped.', 4),
('e5000000-0000-0000-0000-000000000026', 'E', 'Arrange immediate lung resection surgery as first-line treatment', false, 'Ruled out because chest drain insertion (with antibiotics, and intrapleural fibrinolytics or VATS if drainage is inadequate) is the first-line approach; surgical resection is not the initial step.', 5),
('e5000000-0000-0000-0000-000000000027', 'A', 'Perform repeated therapeutic aspirations as needed whenever she becomes symptomatic, with no definitive intervention planned', false, 'Ruled out because although repeat aspiration provides temporary relief, it is not the optimal long-term strategy for a rapidly recurrent effusion; a definitive option should be considered.', 1),
('e5000000-0000-0000-0000-000000000027', 'B', 'Start high-dose oral corticosteroids to reduce pleural fluid production', false, 'Ruled out because corticosteroids are not an established treatment for reducing malignant pleural effusion recurrence; drainage-based definitive strategies are appropriate.', 2),
('e5000000-0000-0000-0000-000000000027', 'C', 'Arrange emergency needle decompression as for a tension pneumothorax', false, 'Ruled out because this is a pleural effusion, not a pneumothorax, and there is no indication of tension physiology; needle decompression is not appropriate here.', 3),
('e5000000-0000-0000-0000-000000000027', 'D', 'Reassure her that recurrence is expected and no further intervention is needed', false, 'Ruled out because recurrent symptomatic malignant effusions significantly impair quality of life and warrant active definitive management, not simple reassurance.', 4),
('e5000000-0000-0000-0000-000000000027', 'E', 'Refer for consideration of an indwelling pleural catheter or talc pleurodesis', true, 'Correct. For recurrent symptomatic malignant pleural effusions with demonstrated response to drainage, definitive management options include an indwelling pleural catheter (allowing ongoing intermittent drainage at home) or chemical pleurodesis (e.g., talc), both aimed at preventing reaccumulation and repeated hospital-based aspirations.', 5),
('e5000000-0000-0000-0000-000000000028', 'A', 'Bordered by the anterior border of latissimus dorsi, the lateral border of pectoralis major, a horizontal line at the level of the nipple (5th intercostal space), and an apex below the axilla', true, 'Correct. The safe triangle for chest drain insertion is bounded by the anterior edge of latissimus dorsi posteriorly, the lateral edge of pectoralis major anteriorly, and a horizontal line at the level of the nipple (approximately the 5th intercostal space) inferiorly, with the apex in the axilla; inserting within this area minimises risk of damage to the breast tissue, major vessels, and abdominal organs.', 1),
('e5000000-0000-0000-0000-000000000028', 'B', 'The second intercostal space in the midclavicular line', false, 'Ruled out because this is the classic site for emergency needle decompression of a tension pneumothorax, not the recommended site for formal chest drain insertion.', 2),
('e5000000-0000-0000-0000-000000000028', 'C', 'Directly over the scapula posteriorly', false, 'Ruled out because this location is not part of the recommended safe triangle and risks injury to the scapula and surrounding musculature without adequate access to the pleural space.', 3),
('e5000000-0000-0000-0000-000000000028', 'D', 'The subcostal margin anteriorly at the level of the umbilicus', false, 'Ruled out because this location risks injury to abdominal organs (liver, spleen) and is well below the appropriate intercostal space for chest drain insertion.', 4),
('e5000000-0000-0000-0000-000000000028', 'E', 'The suprasternal notch', false, 'Ruled out because this is not an appropriate or safe site for pleural drain insertion and carries no relevance to the safe triangle landmarks.', 5),
('e5000000-0000-0000-0000-000000000029', 'A', 'D-dimer testing alone, with no imaging unless it is positive', false, $x$Ruled out because D-dimer is only used to help exclude PE when clinical probability is 'unlikely' (Wells score 4 or less); with a 'likely' score, CTPA should proceed directly regardless of D-dimer.$x$, 1),
('e5000000-0000-0000-0000-000000000029', 'B', 'Doppler ultrasound of the leg only, with no chest imaging', false, 'Ruled out because although leg Doppler can support a diagnosis of DVT, this patient has clear respiratory symptoms and a high pre-test probability for PE; CTPA is required to directly assess the pulmonary vasculature.', 2),
('e5000000-0000-0000-0000-000000000029', 'C', 'Reassure her that her symptoms are most likely musculoskeletal and discharge with analgesia', false, 'Ruled out because this ignores multiple high-risk features for PE (recent immobilisation, tachycardia, leg swelling, hypoxia) and would be unsafe.', 3),
('e5000000-0000-0000-0000-000000000029', 'D', $x$CT pulmonary angiogram (CTPA), as her Wells score classifies PE as 'likely'$x$, true, $x$Correct. Clinical signs of DVT, heart rate over 100, recent immobilisation (long flight), and no alternative diagnosis being more likely together give a Wells score well above 4, classifying PE as 'likely'; in this category, CTPA is the recommended first-line imaging, with interim treatment-dose anticoagulation if CTPA cannot be done immediately.$x$, 4),
('e5000000-0000-0000-0000-000000000029', 'E', 'Arrange an outpatient chest X-ray and review in one week', false, $x$Ruled out because chest X-ray is often normal in PE and does not exclude the diagnosis; with a 'likely' Wells score, urgent CTPA rather than routine outpatient imaging is required.$x$, 5),
('e5000000-0000-0000-0000-000000000030', 'A', 'Start standard treatment-dose low molecular weight heparin alone, without thrombolysis', false, 'Ruled out because anticoagulation alone does not actively dissolve existing clot; in haemodynamically unstable (massive) PE, thrombolysis is needed to rapidly relieve the obstruction and right heart strain.', 1),
('e5000000-0000-0000-0000-000000000030', 'B', 'Systemic thrombolysis (e.g., IV alteplase)', true, 'Correct. This is a massive (high-risk) PE with haemodynamic instability (persistent hypotension unresponsive to fluids); in the absence of major contraindications, systemic thrombolysis is indicated to rapidly reduce clot burden and right ventricular strain, as the risk of death from untreated massive PE outweighs bleeding risk.', 2),
('e5000000-0000-0000-0000-000000000030', 'C', 'Insert a chest drain to relieve suspected tension physiology', false, 'Ruled out because this presentation is due to a confirmed PE causing obstructive shock, not a pneumothorax; a chest drain is not indicated and does not address the underlying pathology.', 3),
('e5000000-0000-0000-0000-000000000030', 'D', 'Perform urgent open surgical embolectomy as the first-line option in all centres', false, 'Ruled out because surgical or catheter-directed embolectomy is reserved for cases where thrombolysis is contraindicated or has failed, and availability is limited; thrombolysis is the first-line intervention where not contraindicated.', 4),
('e5000000-0000-0000-0000-000000000030', 'E', 'Discharge with outpatient anticoagulation once his blood pressure transiently improves after a fluid bolus', false, 'Ruled out because this patient has confirmed massive PE with haemodynamic instability and requires inpatient, likely critical care level, management, not discharge.', 5),
('e5000000-0000-0000-0000-000000000031', 'A', 'Warfarin, started immediately without any parenteral anticoagulant overlap', false, 'Ruled out because warfarin is no longer first-line for most patients with PE, and if used, it requires overlap with a parenteral anticoagulant (e.g., LMWH) until the INR is therapeutic, given its delayed onset of anticoagulant effect.', 1),
('e5000000-0000-0000-0000-000000000031', 'B', 'Low molecular weight heparin alone as definitive long-term treatment in all patients', false, 'Ruled out because although LMWH is preferred in specific situations (e.g., active cancer or pregnancy), it is not the first-line choice for most patients with PE, who are more appropriately managed with a DOAC.', 2),
('e5000000-0000-0000-0000-000000000031', 'C', 'Aspirin alone as sufficient treatment for confirmed PE', false, 'Ruled out because aspirin is not adequate anticoagulation for treating an established venous thromboembolism and is not recommended for this indication.', 3),
('e5000000-0000-0000-0000-000000000031', 'D', 'No anticoagulation is required as this was an unprovoked event and will resolve spontaneously', false, 'Ruled out because confirmed PE requires anticoagulation regardless of whether it was provoked or unprovoked, to treat the acute clot and reduce recurrence risk.', 4),
('e5000000-0000-0000-0000-000000000031', 'E', 'A direct oral anticoagulant (e.g., apixaban or rivaroxaban)', true, 'Correct. For most patients with confirmed PE (without significant renal impairment, active cancer, antiphospholipid syndrome, or pregnancy), current guidance recommends a direct oral anticoagulant as first-line treatment, given comparable efficacy to warfarin with a more favourable safety and monitoring profile.', 5),
('e5000000-0000-0000-0000-000000000032', 'A', 'Left ventricular heart failure', false, 'Ruled out because the echocardiogram shows preserved left ventricular function; the findings (right ventricular hypertrophy and dilatation, loud P2) point to right-sided, not left-sided, heart failure.', 1),
('e5000000-0000-0000-0000-000000000032', 'B', 'Constrictive pericarditis', false, 'Ruled out because although this can cause right-sided congestive signs, it does not explain the echocardiographic finding of right ventricular hypertrophy with raised pulmonary artery pressure, which is a direct consequence of his chronic lung disease.', 2),
('e5000000-0000-0000-0000-000000000032', 'C', 'Cor pulmonale secondary to pulmonary hypertension from chronic COPD', true, 'Correct. Chronic hypoxic pulmonary vasoconstriction in longstanding COPD leads to pulmonary hypertension and consequent right ventricular strain or failure (cor pulmonale), presenting with peripheral oedema, raised JVP, a loud P2, and echocardiographic right heart changes with preserved left ventricular function.', 3),
('e5000000-0000-0000-0000-000000000032', 'D', 'Acute pulmonary embolism', false, 'Ruled out because the chronic, progressive nature of his symptoms alongside long-standing COPD points to a chronic process (cor pulmonale) rather than an acute embolic event.', 4),
('e5000000-0000-0000-0000-000000000032', 'E', 'Primary (idiopathic) pulmonary arterial hypertension', false, 'Ruled out because this diagnosis is reserved for pulmonary hypertension without an identifiable underlying cause; here, his long-standing severe COPD is a clear and common secondary cause.', 5),
('e5000000-0000-0000-0000-000000000033', 'A', 'Withhold any imaging due to concerns about fetal radiation exposure and treat empirically without confirming the diagnosis', false, 'Ruled out because suspected PE must be appropriately investigated; the radiation dose from CTPA or V/Q scanning is considered acceptably low for both mother and fetus when clinically indicated, and an unconfirmed diagnosis has major implications for duration of treatment.', 1),
('e5000000-0000-0000-0000-000000000033', 'B', 'Proceed to definitive chest imaging (CTPA or a perfusion-only/half-dose V/Q scan, per local protocol) without unnecessary delay, since she has no leg symptoms to justify starting with leg ultrasound', true, 'Correct. In pregnancy, if there are symptoms or signs suggestive of DVT, bilateral leg ultrasound is performed first to avoid radiation; here, with no leg symptoms, definitive chest imaging (CTPA or a perfusion-only/half-dose V/Q scan depending on local protocol) should proceed promptly, as suspected PE in pregnancy should never be left uninvestigated because of radiation concerns alone.', 2),
('e5000000-0000-0000-0000-000000000033', 'C', 'Rely on D-dimer testing alone to confirm or exclude PE, given its normal physiological changes in pregnancy', false, 'Ruled out because D-dimer is often physiologically elevated in pregnancy and is not considered reliable for excluding PE in this population; imaging is required.', 3),
('e5000000-0000-0000-0000-000000000033', 'D', 'Repeat the chest X-ray in 24 hours and treat based on this result alone', false, 'Ruled out because chest X-ray has poor sensitivity for PE and is often normal even when PE is present; repeating it does not adequately investigate ongoing clinical suspicion.', 4),
('e5000000-0000-0000-0000-000000000033', 'E', 'Discharge with reassurance, as PE is rare in pregnancy', false, 'Ruled out because pregnancy is a recognised risk factor for VTE due to a hypercoagulable state, and ongoing clinical suspicion warrants active investigation, not discharge.', 5),
('e5000000-0000-0000-0000-000000000034', 'A', 'Mechanical prophylaxis (e.g., intermittent pneumatic compression) plus pharmacological prophylaxis with low molecular weight heparin, started postoperatively and continued for an extended period after discharge', true, 'Correct. Major orthopaedic surgery (such as hip replacement) carries a high VTE risk; standard practice is combined mechanical and pharmacological thromboprophylaxis (typically LMWH), continued for an extended duration (commonly around 4 weeks) after discharge, in the absence of contraindications such as active bleeding.', 1),
('e5000000-0000-0000-0000-000000000034', 'B', 'No VTE prophylaxis is needed as she has no personal history of VTE', false, 'Ruled out because VTE risk assessment is based on procedure- and patient-related risk factors, not solely on prior personal history; major orthopaedic surgery itself confers a high risk requiring prophylaxis.', 2),
('e5000000-0000-0000-0000-000000000034', 'C', 'Aspirin alone, with no mechanical or heparin-based prophylaxis', false, 'Ruled out because LMWH (with mechanical prophylaxis) is generally preferred as more effective standard prophylaxis after major joint replacement in most guidance, rather than aspirin alone.', 3),
('e5000000-0000-0000-0000-000000000034', 'D', 'Full treatment-dose anticoagulation from the time of admission, as if she already has a VTE', false, 'Ruled out because prophylactic, not treatment, doses of anticoagulant are used for VTE prevention in patients without a confirmed VTE; treatment doses are reserved for those with diagnosed DVT or PE.', 4),
('e5000000-0000-0000-0000-000000000034', 'E', 'Mechanical prophylaxis only, with no pharmacological agent, for the entire admission', false, 'Ruled out because given the high VTE risk of major orthopaedic surgery, combined mechanical and pharmacological prophylaxis is recommended rather than mechanical methods alone.', 5),
('e5000000-0000-0000-0000-000000000035', 'A', 'Proceed to CTPA regardless of the D-dimer result, as it should never be used to exclude PE', false, $x$Ruled out because D-dimer is specifically validated to exclude PE in patients with a low ('unlikely') pre-test probability; in this group, a negative result appropriately avoids unnecessary imaging and radiation exposure.$x$, 1),
('e5000000-0000-0000-0000-000000000035', 'B', 'Repeat the D-dimer test in 24 hours before making any further decision', false, $x$Ruled out because a single validated negative D-dimer in a 'PE unlikely' patient is sufficient to exclude PE; there is no need to repeat the test.$x$, 2),
('e5000000-0000-0000-0000-000000000035', 'C', 'Start empirical anticoagulation regardless of the D-dimer result, given his risk factors', false, 'Ruled out because empirical anticoagulation is not indicated once PE has been appropriately excluded by the Wells score and D-dimer pathway; this would expose him to unnecessary bleeding risk.', 3),
('e5000000-0000-0000-0000-000000000035', 'D', 'PE can be safely excluded without further imaging, and alternative diagnoses should be considered', true, $x$Correct. In patients classified as 'PE unlikely' by the two-level Wells score, a negative D-dimer has a high enough negative predictive value to safely rule out PE without the need for CTPA, allowing consideration of alternative diagnoses for his symptoms.$x$, 4),
('e5000000-0000-0000-0000-000000000035', 'E', 'Arrange a V/Q scan instead of relying on the D-dimer result', false, $x$Ruled out because in the 'PE unlikely' category, a negative D-dimer is sufficient to exclude PE without needing further imaging such as V/Q scanning.$x$, 5),
('e5000000-0000-0000-0000-000000000036', 'A', 'A CURB-65 score of 2, suitable for outpatient management with oral antibiotics', false, 'Ruled out because this understates his risk; he meets all five CURB-65 criteria (confusion, urea above 7, RR 30 or more, hypotension, age 65 or over), giving a score of 5, not 2, and outpatient management would be unsafe.', 1),
('e5000000-0000-0000-0000-000000000036', 'B', 'A CURB-65 score of 1, indicating low-severity pneumonia manageable at home', false, 'Ruled out because this significantly underestimates his severity; multiple high-risk criteria are met, and home management would be inappropriate and dangerous given his severity score.', 2),
('e5000000-0000-0000-0000-000000000036', 'C', 'A CURB-65 score of 5, but this only applies to community settings and has no bearing on hospital management decisions', false, 'Ruled out because CURB-65 is specifically used to guide severity assessment and management decisions (including the need for HDU/ICU and IV therapy) in patients presenting with pneumonia, including in hospital.', 3),
('e5000000-0000-0000-0000-000000000036', 'D', 'A CURB-65 score of 5, indicating severe pneumonia requiring consideration of intensive care/HDU input and IV antibiotics', true, 'Correct. He scores one point each for Confusion, Urea above 7 mmol/L, Respiratory rate of 30 or more, Blood pressure (systolic below 90 or diastolic 60 or below), and age 65 or over, giving a total of 5; a CURB-65 score of 3 or more indicates severe pneumonia with high mortality risk, warranting urgent senior review, IV antibiotics, and consideration of HDU/ICU admission.', 4),
('e5000000-0000-0000-0000-000000000036', 'E', 'CURB-65 cannot be calculated because his oxygen saturation is not provided', false, 'Ruled out because oxygen saturation is not one of the five CURB-65 criteria (confusion, urea, respiratory rate, blood pressure, age 65 or over); the score can be fully calculated from the information given.', 5),
('e5000000-0000-0000-0000-000000000037', 'A', 'Broader-spectrum antibiotics covering hospital-acquired pathogens, per local hospital-acquired pneumonia guidelines, rather than standard community-acquired pneumonia therapy', true, 'Correct. Pneumonia developing more than 48 hours after hospital admission is classified as hospital-acquired pneumonia (HAP), which involves a different and often more resistant range of causative organisms than community-acquired pneumonia; local hospital antimicrobial guidelines for HAP (typically broader-spectrum cover) should be followed rather than standard CAP regimens.', 1),
('e5000000-0000-0000-0000-000000000037', 'B', 'Standard first-line community-acquired pneumonia antibiotics (e.g., amoxicillin) as she has no ICU history', false, 'Ruled out because the key determinant is timing of onset (more than 48 hours after admission equals HAP), not ICU exposure; HAP requires different antibiotic cover than CAP regardless of ICU history.', 2),
('e5000000-0000-0000-0000-000000000037', 'C', 'No antibiotics are needed as this is likely a non-infective postoperative complication', false, 'Ruled out because fever, productive cough, new consolidation, and increasing oxygen requirement strongly suggest infective pneumonia requiring prompt antibiotic treatment.', 3),
('e5000000-0000-0000-0000-000000000037', 'D', 'Antifungal therapy as first-line, given her hospital admission', false, 'Ruled out because bacterial pathogens remain the most likely cause of HAP in this context; empirical antifungal therapy is not first-line management.', 4),
('e5000000-0000-0000-0000-000000000037', 'E', 'Discharge her home with oral antibiotics given her background health status', false, 'Ruled out because new hospital-acquired pneumonia with increasing oxygen requirement warrants continued inpatient management and assessment, not discharge.', 5),
('e5000000-0000-0000-0000-000000000038', 'A', 'Direct haematogenous spread of a distant bacterial infection', false, 'Ruled out because there is no evidence of a distant infective source; the clinical context (dysphagia, coughing on meals, dependent lobe consolidation) strongly supports an aspiration mechanism rather than haematogenous spread.', 1),
('e5000000-0000-0000-0000-000000000038', 'B', $x$Primary viral pneumonia unrelated to his Parkinson's disease$x$, false, 'Ruled out because although viral pneumonia is possible in any patient, the specific clinical clues (dysphagia, coughing during meals, dependent lobe involvement) point specifically to aspiration as the mechanism.', 2),
('e5000000-0000-0000-0000-000000000038', 'C', 'Reactivation of latent tuberculosis', false, 'Ruled out because there are no features suggestive of TB (weight loss, night sweats, chronicity, risk factors), and the clinical picture described is classic for aspiration pneumonia.', 3),
('e5000000-0000-0000-0000-000000000038', 'D', 'Pulmonary oedema secondary to undiagnosed heart failure', false, 'Ruled out because although heart failure can cause similar chest X-ray changes, the specific history of dysphagia and coughing during meals, combined with the dependent lobe location, points to aspiration rather than cardiogenic pulmonary oedema.', 4),
('e5000000-0000-0000-0000-000000000038', 'E', 'Aspiration of oropharyngeal or gastric contents due to underlying dysphagia', true, $x$Correct. Parkinson's disease commonly causes dysphagia with impaired swallowing coordination, predisposing to aspiration of food, secretions, or gastric contents into the lungs; the right lower lobe (or the most dependent segment depending on positioning) is a classic site for aspiration pneumonia because of the more vertical orientation of the right main bronchus.$x$, 5),
('e5000000-0000-0000-0000-000000000039', 'A', 'Await full culture and sensitivity results, which can take several weeks, before starting any treatment', false, 'Ruled out because treatment should not be delayed until culture confirmation when smear microscopy is positive and the clinical picture is strongly suggestive; empirical quadruple therapy is started promptly.', 1),
('e5000000-0000-0000-0000-000000000039', 'B', 'Start standard quadruple anti-tuberculous therapy (rifampicin, isoniazid, pyrazinamide, ethambutol), notify public health, and arrange appropriate respiratory isolation', true, 'Correct. A positive AFB smear with this classic clinical and radiological picture (cavitating upper lobe lesion, weight loss, night sweats, haemoptysis) supports starting standard quadruple anti-TB therapy without waiting for full culture confirmation, alongside mandatory notification to public health authorities and appropriate infection control given the risk of person-to-person transmission.', 2),
('e5000000-0000-0000-0000-000000000039', 'C', 'Start treatment with rifampicin monotherapy only, to reduce side effects', false, 'Ruled out because monotherapy in active TB risks rapid development of drug resistance; standard initial treatment requires combination quadruple therapy.', 3),
('e5000000-0000-0000-0000-000000000039', 'D', 'No specific isolation or public health notification is required as this is a chronic, non-urgent condition', false, 'Ruled out because pulmonary TB (particularly smear-positive) is an infectious disease requiring public health notification and appropriate isolation precautions to prevent transmission.', 4),
('e5000000-0000-0000-0000-000000000039', 'E', 'Treat with a standard course of broad-spectrum antibiotics for presumed bacterial pneumonia, reserving anti-TB therapy only if he fails to improve', false, 'Ruled out because the strong clinical suspicion of TB with a positive AFB smear should prompt starting anti-TB therapy directly, not a trial of standard antibiotics first.', 5),
('e5000000-0000-0000-0000-000000000040', 'A', 'Streptococcus pneumoniae', false, 'Ruled out because typical pneumococcal pneumonia usually presents with a productive cough and lobar consolidation without this specific combination of extrapulmonary features (confusion, diarrhoea, hyponatraemia, deranged LFTs) and water exposure history.', 1),
('e5000000-0000-0000-0000-000000000040', 'B', 'Mycoplasma pneumoniae', false, 'Ruled out because although Mycoplasma is another atypical organism causing extrapulmonary features, it is not specifically linked to contaminated water sources such as hot tubs; the water exposure history points more specifically to Legionella.', 2),
('e5000000-0000-0000-0000-000000000040', 'C', 'Legionella pneumophila', true, 'Correct. Exposure to a contaminated water source (e.g., a hotel hot tub), together with fever, dry cough, confusion, diarrhoea, hyponatraemia, and deranged liver function, is classic for Legionella pneumonia, an atypical organism associated with characteristic extrapulmonary features.', 3),
('e5000000-0000-0000-0000-000000000040', 'D', 'Haemophilus influenzae', false, 'Ruled out because this typically causes infection in patients with underlying chronic lung disease and does not classically cause this pattern of systemic extrapulmonary features linked to water exposure.', 4),
('e5000000-0000-0000-0000-000000000040', 'E', 'Pneumocystis jirovecii', false, 'Ruled out because this organism causes pneumonia predominantly in immunocompromised patients (e.g., HIV with a low CD4 count) and is not linked to water exposure or this specific symptom complex.', 5),
('e5000000-0000-0000-0000-000000000041', 'A', 'No antiviral treatment is needed as she is not currently hypoxic or breathless', false, 'Ruled out because antiviral treatment eligibility in high-risk groups is based on risk factors and timing of presentation, not current severity alone; she has real risk of deterioration given her comorbidities.', 1),
('e5000000-0000-0000-0000-000000000041', 'B', 'Start broad-spectrum antibiotics empirically, as this is likely bacterial pneumonia', false, 'Ruled out because her presentation (myalgia, dry cough, sore throat, during a local influenza outbreak) is more consistent with influenza; antibiotics are not first-line unless secondary bacterial infection is suspected.', 2),
('e5000000-0000-0000-0000-000000000041', 'C', 'Start oral oseltamivir, given her high-risk comorbidities and presentation within 48 hours of symptom onset', true, 'Correct. In patients at high risk of influenza complications (such as older age, diabetes, and chronic kidney disease) presenting within 48 hours of symptom onset, antiviral treatment with oseltamivir is recommended to reduce the risk of complications, even in those who are not currently severely unwell.', 3),
('e5000000-0000-0000-0000-000000000041', 'D', 'Reassure her that antivirals are only useful within 24 hours of symptom onset, and it is now too late', false, 'Ruled out because oseltamivir is recommended for high-risk patients presenting within 48 hours of symptom onset, and she is within this window at 36 hours.', 4),
('e5000000-0000-0000-0000-000000000041', 'E', 'Advise annual influenza vaccination now as the sole intervention for her current illness', false, 'Ruled out because vaccination is for future prevention and has no role in treating her current acute infection; antiviral treatment is indicated now given her risk profile and timing.', 5),
('e5000000-0000-0000-0000-000000000042', 'A', 'Pneumocystis jirovecii pneumonia (PJP)', true, 'Correct. A patient with HIV and a CD4 count below 200 cells/microL, presenting with subacute progressive breathlessness, dry cough, exertional desaturation, and bilateral perihilar ground-glass changes on chest X-ray, is classic for Pneumocystis jirovecii pneumonia, an opportunistic infection requiring prompt treatment (typically high-dose co-trimoxazole).', 1),
('e5000000-0000-0000-0000-000000000042', 'B', 'Community-acquired bacterial pneumonia', false, 'Ruled out because bacterial pneumonia typically presents more acutely with focal consolidation, productive cough and fever, rather than this subacute, progressive, bilateral ground-glass pattern with exertional desaturation in a patient with a low CD4 count.', 2),
('e5000000-0000-0000-0000-000000000042', 'C', $x$Pulmonary Kaposi's sarcoma$x$, false, $x$Ruled out because although Kaposi's sarcoma can affect the lungs in advanced HIV, it typically presents with nodular lesions and is often associated with cutaneous or mucosal lesions, rather than this classic subacute PJP presentation.$x$, 3),
('e5000000-0000-0000-0000-000000000042', 'D', 'Pulmonary tuberculosis', false, 'Ruled out because while TB is an important consideration in HIV, the classic subacute presentation with exertional desaturation and bilateral perihilar ground-glass changes, without cavitation or upper lobe predominance, is more typical of PJP.', 4),
('e5000000-0000-0000-0000-000000000042', 'E', 'Chronic obstructive pulmonary disease exacerbation', false, 'Ruled out because there is no history of significant smoking or prior COPD diagnosis, and the clinical and radiological picture here, in the context of newly diagnosed advanced HIV, is much more consistent with an opportunistic infection.', 5),
('e5000000-0000-0000-0000-000000000043', 'A', 'Generalised anxiety disorder', false, 'Ruled out because this does not explain witnessed apnoeic episodes, loud snoring, or the physical risk factors (obesity, large neck circumference) described; the clinical picture points specifically to a sleep-related breathing disorder.', 1),
('e5000000-0000-0000-0000-000000000043', 'B', 'Narcolepsy', false, 'Ruled out because narcolepsy classically presents with sudden irresistible sleep attacks, cataplexy, and other REM-related phenomena, rather than the combination of snoring, witnessed apnoeas, obesity, and hypertension described here.', 2),
('e5000000-0000-0000-0000-000000000043', 'C', 'Chronic insomnia disorder', false, 'Ruled out because insomnia refers to difficulty initiating or maintaining sleep, not excessive daytime sleepiness with witnessed breathing pauses during sleep; this presentation is inconsistent with a primary insomnia disorder.', 3),
('e5000000-0000-0000-0000-000000000043', 'D', 'Depression with associated fatigue', false, 'Ruled out because although fatigue can occur in depression, the specific findings of witnessed apnoea, loud snoring, obesity, and large neck circumference point strongly towards a sleep-related breathing disorder rather than a primary mood disorder.', 4),
('e5000000-0000-0000-0000-000000000043', 'E', 'Obstructive sleep apnoea', true, 'Correct. Loud snoring, witnessed apnoeic episodes, excessive daytime sleepiness (including near-miss driving incidents), obesity, a large neck circumference, and hypertension together are highly suggestive of obstructive sleep apnoea, and this presentation warrants urgent assessment and, critically, safety advice regarding driving.', 5),
('e5000000-0000-0000-0000-000000000044', 'A', 'He can continue driving as normal as long as he starts treatment within the next few weeks', false, 'Ruled out because if his excessive sleepiness is likely to impair safe driving, he must stop driving immediately and notify the DVLA, not continue while awaiting treatment to take effect.', 1),
('e5000000-0000-0000-0000-000000000044', 'B', 'He must stop driving and inform the DVLA immediately, and can only resume once his symptoms are adequately controlled and this is confirmed through the appropriate specialist/DVLA process', true, 'Correct. Any driver, particularly a Group 2 (HGV) licence holder, with excessive sleepiness likely to impair driving due to obstructive sleep apnoea must stop driving and notify the DVLA; Group 2 drivers face stricter requirements and can only resume driving once symptoms are controlled, confirmed by specialist assessment, given the higher-risk nature of large vehicle driving.', 2),
('e5000000-0000-0000-0000-000000000044', 'C', 'He only needs to inform his employer, not the DVLA, as this is a medical confidentiality matter', false, 'Ruled out because DVLA notification is a legal requirement for conditions that may affect fitness to drive, particularly for safety-critical vehicle categories like Group 2 licences; this is not solely an employer matter.', 3),
('e5000000-0000-0000-0000-000000000044', 'D', 'He can continue driving because OSA does not affect legal fitness to drive', false, 'Ruled out because OSA causing excessive sleepiness that could impair driving is a recognised condition affecting fitness to drive and is notifiable to the DVLA.', 4),
('e5000000-0000-0000-0000-000000000044', 'E', 'He should stop driving only if he has previously had a road traffic accident', false, 'Ruled out because the requirement to stop driving and notify the DVLA is based on the presence of impairing symptoms, not on whether an accident has already occurred; waiting for an accident is unsafe practice.', 5),
('e5000000-0000-0000-0000-000000000045', 'A', 'Simple obstructive sleep apnoea without hypoventilation', false, 'Ruled out because simple OSA does not typically cause sustained daytime hypercapnia and a raised bicarbonate while awake; the presence of daytime hypoventilation defines obesity hypoventilation syndrome as distinct from OSA alone, although the two frequently coexist.', 1),
('e5000000-0000-0000-0000-000000000045', 'B', 'Chronic obstructive pulmonary disease', false, 'Ruled out because spirometry shows a restrictive, not obstructive, pattern attributable to obesity, and there is no smoking history or other evidence of COPD provided.', 2),
('e5000000-0000-0000-0000-000000000045', 'C', 'Primary hypothyroidism as the sole explanation', false, 'Ruled out because although hypothyroidism can contribute to hypoventilation and should be excluded, the clinical picture (severe obesity, daytime hypercapnia, restrictive pattern from body habitus) is most consistent with obesity hypoventilation syndrome as the primary diagnosis.', 3),
('e5000000-0000-0000-0000-000000000045', 'D', 'Obesity hypoventilation syndrome', true, 'Correct. Severe obesity with daytime hypercapnia (awake PaCO2 above 6 kPa) and a compensatory raised bicarbonate, in the absence of another cause for hypoventilation (e.g., significant primary lung disease, neuromuscular disease), is characteristic of obesity hypoventilation syndrome, often accompanied by obstructive sleep apnoea and features of right heart strain (peripheral oedema) from chronic hypoxaemia and hypercapnia.', 4),
('e5000000-0000-0000-0000-000000000045', 'E', 'Idiopathic pulmonary fibrosis', false, 'Ruled out because there is no history or examination findings (e.g., clubbing, bibasal crackles) suggestive of pulmonary fibrosis, and the restrictive pattern here is attributed to her body habitus rather than parenchymal lung disease.', 5),
('e5000000-0000-0000-0000-000000000046', 'A', 'Increase the inspired oxygen concentration further to correct his hypoxaemia as the priority', false, 'Ruled out because in a CO2 retainer with respiratory acidosis, simply increasing oxygen further risks worsening hypercapnia; the priority is addressing ventilation with NIV, not just oxygenation.', 1),
('e5000000-0000-0000-0000-000000000046', 'B', 'Proceed immediately to invasive mechanical ventilation without a trial of NIV', false, 'Ruled out because NIV is first-line for this scenario (persistent hypercapnic acidosis despite medical therapy, no contraindications); invasive ventilation is reserved for NIV failure, intolerance, or contraindication.', 2),
('e5000000-0000-0000-0000-000000000046', 'C', 'Start non-invasive ventilation (NIV, e.g., BiPAP)', true, 'Correct. Persistent hypercapnic respiratory acidosis (pH below 7.35, elevated PaCO2) despite optimal initial medical therapy for a COPD exacerbation is the key indication for starting non-invasive ventilation, which reduces the work of breathing and improves ventilation, reducing the need for invasive mechanical ventilation and improving outcomes.', 3),
('e5000000-0000-0000-0000-000000000046', 'D', 'Administer a further dose of nebulised bronchodilators alone and repeat the ABG in 4 hours without other intervention', false, 'Ruled out because this delays initiation of NIV, which is indicated now given the persistent acidosis despite already-optimised medical therapy.', 4),
('e5000000-0000-0000-0000-000000000046', 'E', 'Give IV sodium bicarbonate to correct the acidosis rather than addressing ventilation', false, 'Ruled out because treating the underlying hypoventilation with NIV is the appropriate approach to a respiratory acidosis, not simply buffering with bicarbonate, which does not address the underlying problem.', 5),
('e5000000-0000-0000-0000-000000000047', 'A', 'Type 2 respiratory failure, because her PaO2 is low', false, 'Ruled out because type 2 respiratory failure requires both hypoxaemia and hypercapnia (raised PaCO2); her PaCO2 is normal to low, so this is type 1, not type 2, respiratory failure.', 1),
('e5000000-0000-0000-0000-000000000047', 'B', 'Type 1 respiratory failure (hypoxaemia with a normal or low PaCO2)', true, 'Correct. She has hypoxaemia (PaO2 below 8 kPa, even on supplemental oxygen) with a normal-to-low PaCO2 and normal pH; this pattern, typically seen in conditions causing ventilation-perfusion mismatch such as pneumonia, defines type 1 respiratory failure.', 2),
('e5000000-0000-0000-0000-000000000047', 'C', 'No respiratory failure, as her pH is within the normal range', false, 'Ruled out because a normal pH does not exclude respiratory failure; type 1 respiratory failure is defined by hypoxaemia (PaO2 below 8 kPa) regardless of pH, which here is compensated and normal.', 3),
('e5000000-0000-0000-0000-000000000047', 'D', 'Type 2 respiratory failure with compensated respiratory acidosis', false, 'Ruled out because there is no acidosis (pH is normal) and no hypercapnia; this description does not match her ABG values.', 4),
('e5000000-0000-0000-0000-000000000047', 'E', 'Mixed type 1 and type 2 respiratory failure', false, 'Ruled out because mixed failure would require evidence of both hypoxaemia and hypercapnia; her PaCO2 is not elevated, so only type 1 features are present.', 5),
('e5000000-0000-0000-0000-000000000048', 'A', '94-98%, as for the general population without respiratory disease', false, 'Ruled out because this target is appropriate for patients not at risk of hypercapnic respiratory failure; his known COPD with previous hypercapnic failure means a lower target (88-92%) should be used to avoid worsening hypercapnia.', 1),
('e5000000-0000-0000-0000-000000000048', 'B', '100%, to ensure maximal oxygenation at all times', false, 'Ruled out because driving saturations to 100% with high-flow oxygen in a CO2 retainer risks suppressing hypoxic drive and worsening hypercapnia and acidosis, which can be dangerous.', 2),
('e5000000-0000-0000-0000-000000000048', 'C', 'No oxygen should be given at all, regardless of his saturation, due to the risk of hypercapnia', false, 'Ruled out because oxygen should not be withheld entirely if he is hypoxic; it should be carefully titrated to the 88-92% target range rather than avoided altogether.', 3),
('e5000000-0000-0000-0000-000000000048', 'D', '88-92%', true, 'Correct. Patients with a history of hypercapnic respiratory failure (such as this patient with known COPD and a previous episode) are at risk of oxygen-induced hypercapnia if given uncontrolled high-flow oxygen; the recommended target saturation range for such patients is 88-92%, delivered via a titrated (e.g., Venturi) device, until blood gases confirm the safety of a higher target.', 4),
('e5000000-0000-0000-0000-000000000048', 'E', '85-88%, as a stricter lower target reduces risk further', false, 'Ruled out because the recommended target range for patients at risk of hypercapnic respiratory failure is 88-92%, not a lower range, which would risk underoxygenation.', 5),
('e5000000-0000-0000-0000-000000000049', 'A', 'Continuous positive airway pressure (CPAP) therapy', true, 'Correct. For moderate-to-severe obstructive sleep apnoea with significant symptoms (daytime sleepiness), CPAP is the first-line treatment, providing continuous positive pressure to prevent upper airway collapse during sleep and improving both sleep quality and daytime symptoms.', 1),
('e5000000-0000-0000-0000-000000000049', 'B', 'A mandibular advancement device as first-line therapy', false, 'Ruled out because mandibular advancement devices are generally considered for mild OSA or in patients who cannot tolerate CPAP, rather than as first-line therapy for moderate-to-severe symptomatic OSA.', 2),
('e5000000-0000-0000-0000-000000000049', 'C', 'Long-term home oxygen therapy', false, 'Ruled out because home oxygen does not address the underlying upper airway obstruction causing apnoeic events and is not standard treatment for OSA.', 3),
('e5000000-0000-0000-0000-000000000049', 'D', 'Surgical uvulopalatopharyngoplasty as first-line treatment', false, 'Ruled out because surgical options are generally reserved for specific anatomical abnormalities or cases where CPAP is not tolerated or effective, not as routine first-line therapy.', 4),
('e5000000-0000-0000-0000-000000000049', 'E', 'Reassurance that lifestyle measures (weight loss, reduced alcohol) alone are sufficient, with no device-based therapy needed', false, 'Ruled out because although lifestyle measures are valuable adjuncts, moderate-to-severe symptomatic OSA (AHI of 22 per hour with significant daytime sleepiness) warrants CPAP therapy alongside lifestyle changes, not lifestyle measures alone.', 5),
('e5000000-0000-0000-0000-000000000050', 'A', 'Obstructive sleep apnoea due to upper airway collapse', false, 'Ruled out because obstructive sleep apnoea typically presents with loud snoring and is associated with obesity or anatomical airway narrowing, neither of which is present here; the cyclical waxing/waning breathing pattern described is characteristic of a central, not obstructive, process.', 1),
('e5000000-0000-0000-0000-000000000050', 'B', 'Primary insomnia disorder', false, 'Ruled out because insomnia refers to difficulty initiating or maintaining sleep rather than an abnormal breathing pattern during sleep; the described cyclical breathing pattern points to a specific sleep-disordered breathing condition.', 2),
('e5000000-0000-0000-0000-000000000050', 'C', 'Nocturnal asthma exacerbations', false, 'Ruled out because there is no history of wheeze, known asthma, or bronchospasm-related symptoms; the pattern described is a central ventilatory control abnormality related to his heart failure, not airway bronchospasm.', 3),
('e5000000-0000-0000-0000-000000000050', 'D', 'Narcolepsy with associated sleep-related breathing changes', false, 'Ruled out because narcolepsy is characterised by excessive daytime sleepiness with cataplexy or other REM-related phenomena, not this specific cyclical central breathing pattern linked to heart failure.', 4),
('e5000000-0000-0000-0000-000000000050', 'E', 'Central sleep apnoea with Cheyne-Stokes breathing pattern, related to his heart failure', true, 'Correct. The described cyclical waxing-and-waning breathing pattern with central pauses (Cheyne-Stokes respiration), occurring in a patient with reduced ejection fraction heart failure and without typical obstructive features (obesity, loud snoring), is characteristic of central sleep apnoea secondary to heart failure, resulting from an unstable ventilatory control system with delayed feedback.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e5000000-0000-0000-0000-000000000001', 'Acute severe asthma: PEFR 33-50% predicted, RR ≥25, HR ≥110, inability to complete sentences in one breath.', 1),
('e5000000-0000-0000-0000-000000000001', 'Life-threatening features include silent chest, cyanosis, exhaustion, arrhythmia, hypotension, PEFR <33%, SpO2 <92%, and a normal/raised PaCO2.', 2),
('e5000000-0000-0000-0000-000000000001', 'Management ladder: oxygen, nebulised salbutamol +/- ipratropium, oral/IV steroids, then IV magnesium sulfate if not responding, with senior/ICU input for life-threatening features.', 3),
('e5000000-0000-0000-0000-000000000002', 'COPD patients at risk of chronic type 2 respiratory failure should have oxygen titrated to SpO2 88-92% using Venturi masks, with the target range documented on the prescription.', 1),
('e5000000-0000-0000-0000-000000000002', 'A flapping tremor and drowsiness with hypercapnia and acidosis on ABG suggests CO2 narcosis, often precipitated by uncontrolled high-flow oxygen.', 2),
('e5000000-0000-0000-0000-000000000002', 'NIV (BiPAP) is indicated for persistent hypercapnic acidosis (pH<7.35, raised PaCO2) despite optimal medical therapy in a COPD exacerbation.', 3),
('e5000000-0000-0000-0000-000000000003', 'Life-threatening asthma features: silent chest, cyanosis, feeble respiratory effort, exhaustion or confusion, arrhythmia or hypotension, PEFR <33% predicted, SpO2 <92%, and a normal or raised PaCO2.', 1),
('e5000000-0000-0000-0000-000000000003', $x$A 'normal' PaCO2 in an acute severe asthma attack is a warning sign, not reassuring, because tachypnoeic patients should be hypocapnic; a rising PaCO2 indicates fatigue and approaching respiratory arrest.$x$, 2),
('e5000000-0000-0000-0000-000000000003', 'Life-threatening features warrant immediate senior clinician and critical care/anaesthetic involvement alongside continued maximal bronchodilator and steroid therapy.', 3),
('e5000000-0000-0000-0000-000000000004', 'Stepwise COPD inhaler therapy: SABA/SAMA as needed, then LABA plus LAMA; add ICS (triple therapy) if exacerbations continue, especially with blood eosinophils ≥300 cells/microL or asthmatic features.', 1),
('e5000000-0000-0000-0000-000000000004', 'Long-term oral corticosteroids are avoided in stable COPD maintenance because of systemic side effects.', 2),
('e5000000-0000-0000-0000-000000000004', 'Raised blood eosinophils in COPD predict a greater exacerbation-reduction benefit from adding inhaled corticosteroids.', 3),
('e5000000-0000-0000-0000-000000000005', $x$Bronchiectasis: chronic productive cough with purulent sputum, recurrent infections, and HRCT showing bronchial dilatation ('signet ring' sign) and wall thickening.$x$, 1),
('e5000000-0000-0000-0000-000000000005', 'Airway clearance physiotherapy is the cornerstone of chronic management, reducing sputum retention and exacerbation frequency.', 2),
('e5000000-0000-0000-0000-000000000005', 'Antibiotics for exacerbations should be guided by sputum culture and sensitivities where possible.', 3),
('e5000000-0000-0000-0000-000000000006', 'Frequent SABA use (more than one inhaler per month) is a marker of poor asthma control and increased risk of severe exacerbation or death.', 1),
('e5000000-0000-0000-0000-000000000006', 'The standard step-up from SABA-only treatment is a regular inhaled corticosteroid preventer (or a MART/ICS-formoterol regimen per current guidelines).', 2),
('e5000000-0000-0000-0000-000000000006', 'Night-time symptoms and reliever overuse should prompt proactive escalation rather than routine annual review.', 3),
('e5000000-0000-0000-0000-000000000007', 'LTOT is offered to stable COPD patients with PaO2 <7.3 kPa on air, or <8 kPa with evidence of secondary polycythaemia, peripheral oedema, or pulmonary hypertension, confirmed on two ABGs 3 weeks apart when clinically stable.', 1),
('e5000000-0000-0000-0000-000000000007', 'LTOT improves survival in chronically hypoxaemic COPD patients and should be used for at least 15 hours a day.', 2),
('e5000000-0000-0000-0000-000000000007', 'Continued smoking is a contraindication to home oxygen because of fire and explosion risk.', 3),
('e5000000-0000-0000-0000-000000000008', 'Idiopathic pulmonary fibrosis classically presents with progressive dyspnoea, dry cough, bibasal fine crackles, and clubbing in older patients.', 1),
('e5000000-0000-0000-0000-000000000008', 'A UIP pattern on HRCT (subpleural/basal reticulation, honeycombing, traction bronchiectasis, minimal ground-glass) can be diagnostic without biopsy.', 2),
('e5000000-0000-0000-0000-000000000008', 'IPF carries a poor prognosis; antifibrotic agents (e.g., pirfenidone, nintedanib) may slow progression but do not reverse fibrosis.', 3),
('e5000000-0000-0000-0000-000000000009', 'Hypersensitivity pneumonitis is triggered by inhaled organic antigens (e.g., avian proteins, mouldy hay); symptoms often improve away from the exposure and recur on re-exposure.', 1),
('e5000000-0000-0000-0000-000000000009', 'HRCT typically shows ground-glass opacities, poorly defined centrilobular nodules, and mosaic attenuation, often mid/upper zone predominant.', 2),
('e5000000-0000-0000-0000-000000000009', 'Antigen avoidance is the cornerstone of management to prevent progression to chronic fibrotic disease.', 3),
('e5000000-0000-0000-0000-000000000010', 'Löfgren syndrome (an acute form of sarcoidosis) presents with erythema nodosum, bilateral hilar lymphadenopathy, and polyarthralgia, and usually resolves spontaneously.', 1),
('e5000000-0000-0000-0000-000000000010', 'Hypercalcaemia in sarcoidosis results from increased extra-renal conversion of vitamin D by activated macrophages within granulomas.', 2),
('e5000000-0000-0000-0000-000000000010', 'A raised serum ACE can support the diagnosis but is neither sensitive nor specific and is not required for diagnosis.', 3),
('e5000000-0000-0000-0000-000000000011', 'Amiodarone is a recognised cause of drug-induced interstitial lung disease and pulmonary fibrosis, particularly with long-term use.', 1),
('e5000000-0000-0000-0000-000000000011', 'Management centres on prompt cessation of the offending drug (balanced against the indication for it) plus respiratory investigation (HRCT, pulmonary function tests).', 2),
('e5000000-0000-0000-0000-000000000011', 'Other drugs associated with pulmonary toxicity/fibrosis include methotrexate, nitrofurantoin, and bleomycin.', 3),
('e5000000-0000-0000-0000-000000000012', 'Acute hypersensitivity pneumonitis presents 4-8 hours after antigen exposure with fever, breathlessness, cough, and myalgia, resolving within days of avoidance.', 1),
('e5000000-0000-0000-0000-000000000012', $x$Farmer's lung is caused by thermophilic actinomycetes in mouldy hay; repeated exposure risks progression to chronic fibrotic hypersensitivity pneumonitis.$x$, 2),
('e5000000-0000-0000-0000-000000000012', 'Key management is identifying and avoiding the causative antigen; recurrent episodes warrant occupational and environmental review.', 3),
('e5000000-0000-0000-0000-000000000013', 'Interstitial lung disease is a major cause of morbidity and mortality in systemic sclerosis and should be actively screened for with pulmonary function tests and HRCT.', 1),
('e5000000-0000-0000-0000-000000000013', 'A disproportionately reduced DLCO relative to FVC can also indicate coexisting pulmonary vascular disease (pulmonary arterial hypertension) in systemic sclerosis.', 2),
('e5000000-0000-0000-0000-000000000013', 'Connective tissue diseases (rheumatoid arthritis, systemic sclerosis, dermatomyositis) are important causes of secondary interstitial lung disease.', 3),
('e5000000-0000-0000-0000-000000000014', 'Asbestosis has a long latency (often 20-40 years) between exposure and symptom onset, and causes progressive lower-zone predominant pulmonary fibrosis.', 1),
('e5000000-0000-0000-0000-000000000014', 'Pleural plaques are a marker of asbestos exposure and are usually asymptomatic but support the diagnosis when parenchymal fibrosis is present.', 2),
('e5000000-0000-0000-0000-000000000014', 'Asbestos exposure also increases the risk of mesothelioma and bronchial carcinoma; patients may be eligible for industrial injuries compensation.', 3),
('e5000000-0000-0000-0000-000000000015', 'Persistent cough (>3 weeks), unexplained weight loss, haemoptysis, and a significant smoking history in patients over 40 are red flags warranting urgent lung cancer investigation.', 1),
('e5000000-0000-0000-0000-000000000015', 'A normal chest X-ray does not exclude lung cancer; guidance recommends urgent CT chest referral when clinical suspicion remains high.', 2),
('e5000000-0000-0000-0000-000000000015', 'The urgent suspected-cancer pathway aims for rapid diagnosis and staging to enable timely treatment.', 3),
('e5000000-0000-0000-0000-000000000016', $x$Small cell lung cancer is classically associated with paraneoplastic SIADH (ectopic ADH) and ectopic ACTH secretion (Cushing's syndrome), as well as Lambert-Eaton myasthenic syndrome.$x$, 1),
('e5000000-0000-0000-0000-000000000016', 'SIADH causes euvolaemic hyponatraemia with inappropriately concentrated urine relative to plasma osmolality.', 2),
('e5000000-0000-0000-0000-000000000016', 'Management of SIADH-related hyponatraemia includes fluid restriction and treating the underlying malignancy; severe or symptomatic hyponatraemia may need specialist input with careful correction to avoid osmotic demyelination.', 3),
('e5000000-0000-0000-0000-000000000017', 'Superior vena cava obstruction presents with facial/periorbital swelling, distended neck veins, and dilated chest wall collateral veins, often worsened by bending forward or lying flat.', 1),
('e5000000-0000-0000-0000-000000000017', 'It is most commonly caused by extrinsic compression or invasion from bronchial carcinoma or mediastinal lymphadenopathy.', 2),
('e5000000-0000-0000-0000-000000000017', 'Management includes urgent oncology input, dexamethasone to reduce tumour-related oedema, and consideration of vascular stenting or radiotherapy depending on the underlying cause and urgency.', 3),
('e5000000-0000-0000-0000-000000000018', $x$A Pancoast tumour is an apical lung cancer that can invade the brachial plexus (causing arm pain, weakness, and small hand muscle wasting) and the sympathetic chain (causing Horner's syndrome: ptosis, miosis, anhidrosis).$x$, 1),
('e5000000-0000-0000-0000-000000000018', $x$Horner's syndrome combined with signs of brachial plexus involvement in a smoker should prompt urgent imaging (chest X-ray/CT) to look for an apical lung tumour.$x$, 2),
('e5000000-0000-0000-0000-000000000018', 'Pancoast tumours are often diagnosed later due to their location, and can present with bone pain from rib or vertebral invasion.', 3),
('e5000000-0000-0000-0000-000000000019', 'Squamous cell lung carcinoma is a classic cause of humoral hypercalcaemia of malignancy via PTHrP secretion, which suppresses native PTH.', 1),
('e5000000-0000-0000-0000-000000000019', $x$Hypercalcaemia of malignancy presents with confusion, constipation, polyuria, and dehydration ('bones, stones, groans, moans').$x$, 2),
('e5000000-0000-0000-0000-000000000019', 'Initial management of severe hypercalcaemia includes IV fluid rehydration followed by IV bisphosphonates once rehydrated.', 3),
('e5000000-0000-0000-0000-000000000020', 'Incidental solitary pulmonary nodules require further characterisation with CT chest, as chest X-ray alone cannot reliably distinguish benign from malignant nodules.', 1),
('e5000000-0000-0000-0000-000000000020', 'Risk stratification uses factors such as size, growth rate, morphology (spiculated margins increase suspicion), and patient risk factors (smoking, age) to guide further management (surveillance, PET-CT, or biopsy).', 2),
('e5000000-0000-0000-0000-000000000020', 'Nodules with no prior imaging for comparison cannot be assumed stable, and appropriate follow-up imaging intervals depend on size and risk.', 3),
('e5000000-0000-0000-0000-000000000021', 'Mesothelioma is strongly associated with prior asbestos exposure, often with a latency of 20-40 years, and typically presents with pleuritic chest pain, breathlessness, and pleural effusion/thickening.', 1),
('e5000000-0000-0000-0000-000000000021', 'Pleural fluid in mesothelioma is often bloodstained; diagnosis usually requires pleural biopsy (e.g., via thoracoscopy) rather than fluid cytology alone, as cytology can be falsely negative.', 2),
('e5000000-0000-0000-0000-000000000021', 'Patients with occupational asbestos-related mesothelioma may be eligible for industrial compensation; prognosis is generally poor.', 3),
('e5000000-0000-0000-0000-000000000022', 'Tension pneumothorax is a clinical diagnosis (unilateral absent breath sounds, hyper-resonance, tracheal deviation away from the affected side, distended neck veins, hypotension) and must not await chest X-ray confirmation.', 1),
('e5000000-0000-0000-0000-000000000022', 'Immediate management is needle decompression (or finger thoracostomy) followed promptly by formal chest drain insertion.', 2),
('e5000000-0000-0000-0000-000000000022', 'Positive-pressure ventilation in an undrained tension pneumothorax can precipitate cardiovascular collapse.', 3),
('e5000000-0000-0000-0000-000000000023', 'Current guidance favours conservative management for primary spontaneous pneumothorax in stable patients with minimal symptoms, irrespective of pneumothorax size.', 1),
('e5000000-0000-0000-0000-000000000023', 'Intervention (needle aspiration, then chest drain if unsuccessful) is reserved for patients with significant breathlessness or haemodynamic compromise.', 2),
('e5000000-0000-0000-0000-000000000023', 'Safe discharge requires clear safety-netting advice and arranged follow-up imaging to confirm resolution.', 3),
('e5000000-0000-0000-0000-000000000024', 'Secondary pneumothorax (occurring in patients with underlying lung disease, e.g., COPD) is managed more cautiously than primary pneumothorax, as these patients have less respiratory reserve.', 1),
('e5000000-0000-0000-0000-000000000024', 'Chest drain insertion is indicated in secondary pneumothorax when the patient is significantly breathless and/or the rim of air is 2cm or more, or when age is over 50 with a significant rim.', 2),
('e5000000-0000-0000-0000-000000000024', 'All patients with secondary pneumothorax should typically be admitted for observation given the higher risk of deterioration.', 3),
('e5000000-0000-0000-0000-000000000025', $x$Light's criteria classify pleural effusions as exudates if the pleural fluid to serum protein ratio is >0.5, the pleural fluid to serum LDH ratio is >0.6, or the pleural fluid LDH exceeds the upper limit of normal for serum LDH.$x$, 1),
('e5000000-0000-0000-0000-000000000025', 'Common causes of transudative effusions include heart failure, liver cirrhosis, and hypoalbuminaemia; exudative causes include infection, malignancy, and inflammatory conditions.', 2),
('e5000000-0000-0000-0000-000000000025', $x$Light's criteria have high sensitivity for exudates but can occasionally misclassify transudates (e.g., in diuretic-treated heart failure) as exudates, so clinical correlation remains important.$x$, 3),
('e5000000-0000-0000-0000-000000000026', 'Empyema is diagnosed by frankly purulent pleural fluid, or a pleural fluid pH below 7.2 in the context of a parapneumonic effusion, and requires drainage via chest tube in addition to antibiotics.', 1),
('e5000000-0000-0000-0000-000000000026', 'Persistent sepsis despite antibiotics in a patient with pneumonia should prompt reassessment for a complicated parapneumonic effusion or empyema.', 2),
('e5000000-0000-0000-0000-000000000026', 'If drainage is inadequate despite a chest drain, intrapleural fibrinolytics or surgical intervention (VATS decortication) may be required.', 3),
('e5000000-0000-0000-0000-000000000027', 'Malignant pleural effusions frequently recur after simple aspiration; definitive management options include indwelling pleural catheters or chemical pleurodesis.', 1),
('e5000000-0000-0000-0000-000000000027', 'Indwelling pleural catheters allow intermittent outpatient drainage and are particularly useful in patients with a shorter prognosis or trapped lung.', 2),
('e5000000-0000-0000-0000-000000000027', 'Pleurodesis requires reasonable lung re-expansion after drainage to be effective and is generally more suitable for patients with better prognosis and performance status.', 3),
('e5000000-0000-0000-0000-000000000028', 'The safe triangle for chest drain insertion is bounded by the anterior border of latissimus dorsi, the lateral border of pectoralis major, and a horizontal line at the nipple level (5th intercostal space), with its apex in the axilla.', 1),
('e5000000-0000-0000-0000-000000000028', 'Inserting within the safe triangle reduces the risk of injury to the long thoracic nerve, intercostal vessels and nerves, breast tissue, and abdominal organs.', 2),
('e5000000-0000-0000-0000-000000000028', 'Ultrasound guidance is recommended for pleural procedures where available to reduce complications such as organ puncture.', 3),
('e5000000-0000-0000-0000-000000000029', $x$The two-level Wells score stratifies patients into 'PE likely' (more than 4 points) or 'PE unlikely' (4 points or fewer); 'likely' patients proceed directly to CTPA.$x$, 1),
('e5000000-0000-0000-0000-000000000029', $x$In 'PE unlikely' patients, a negative D-dimer can safely exclude PE without imaging; in 'PE likely' patients, D-dimer is not used to rule out PE.$x$, 2),
('e5000000-0000-0000-0000-000000000029', 'If CTPA cannot be performed immediately, interim therapeutic anticoagulation should be started while awaiting imaging.', 3),
('e5000000-0000-0000-0000-000000000030', 'Massive (high-risk) PE is defined by persistent hypotension or shock due to right ventricular failure; it carries high mortality and is an indication for thrombolysis if not contraindicated.', 1),
('e5000000-0000-0000-0000-000000000030', 'Systemic thrombolysis rapidly reduces clot burden and pulmonary artery pressure but carries a significant bleeding risk, which must be weighed against absolute and relative contraindications.', 2),
('e5000000-0000-0000-0000-000000000030', 'Catheter-directed thrombolysis or surgical embolectomy are alternatives when systemic thrombolysis is contraindicated or unavailable.', 3),
('e5000000-0000-0000-0000-000000000031', 'DOACs (e.g., apixaban, rivaroxaban) are first-line for most patients with confirmed VTE, given comparable efficacy to warfarin without the need for routine monitoring.', 1),
('e5000000-0000-0000-0000-000000000031', 'LMWH remains preferred in specific populations, such as active cancer-associated thrombosis or pregnancy, where DOACs are less established or contraindicated.', 2),
('e5000000-0000-0000-0000-000000000031', 'Unprovoked PE requires the same acute anticoagulation as provoked PE, though it prompts consideration of extended-duration anticoagulation and possible investigation for underlying causes depending on individual risk factors.', 3),
('e5000000-0000-0000-0000-000000000032', 'Cor pulmonale refers to right ventricular hypertrophy or failure secondary to chronic lung disease-induced pulmonary hypertension, most commonly from COPD.', 1),
('e5000000-0000-0000-0000-000000000032', 'Chronic hypoxia causes pulmonary vasoconstriction, increasing pulmonary vascular resistance and right ventricular afterload over time.', 2),
('e5000000-0000-0000-0000-000000000032', 'Management focuses on optimising the underlying lung disease (including long-term oxygen therapy where hypoxaemic) and managing fluid overload; specific pulmonary vasodilator therapies are generally not used in COPD-related pulmonary hypertension.', 3),
('e5000000-0000-0000-0000-000000000033', 'Pregnancy is a hypercoagulable state and an independent risk factor for VTE; D-dimer is unreliable for excluding PE in pregnancy because of physiological elevation.', 1),
('e5000000-0000-0000-0000-000000000033', 'If DVT symptoms or signs are present, bilateral leg ultrasound is performed first to avoid unnecessary radiation exposure; if this is negative or there are no leg symptoms, definitive imaging (CTPA or V/Q scan) should not be delayed.', 2),
('e5000000-0000-0000-0000-000000000033', 'LMWH, not DOACs or warfarin, is the anticoagulant of choice for VTE in pregnancy.', 3),
('e5000000-0000-0000-0000-000000000034', 'Major orthopaedic surgery (hip or knee replacement) confers high VTE risk; standard prophylaxis combines mechanical methods (e.g., compression devices) with pharmacological agents (typically LMWH).', 1),
('e5000000-0000-0000-0000-000000000034', 'Extended prophylaxis duration after hip replacement (commonly around 4 weeks) is recommended given the persisting risk period post-discharge.', 2),
('e5000000-0000-0000-0000-000000000034', 'VTE risk assessment should be performed for all surgical inpatients, balancing thrombotic risk against bleeding risk.', 3),
('e5000000-0000-0000-0000-000000000035', $x$The two-level Wells score is used to stratify patients before D-dimer testing; a negative D-dimer safely excludes PE only in patients classified as 'PE unlikely.'$x$, 1),
('e5000000-0000-0000-0000-000000000035', $x$In 'PE likely' patients, D-dimer should not be used to exclude PE; these patients proceed directly to CTPA.$x$, 2),
('e5000000-0000-0000-0000-000000000035', 'D-dimer has high sensitivity but low specificity for PE and can be raised in many other conditions (infection, malignancy, pregnancy, recent surgery).', 3),
('e5000000-0000-0000-0000-000000000036', 'CURB-65: Confusion, Urea above 7 mmol/L, Respiratory rate of 30 or more per minute, Blood pressure (systolic below 90 or diastolic 60 mmHg or below), Age 65 or over - one point each.', 1),
('e5000000-0000-0000-0000-000000000036', 'Score 0-1: low severity (consider outpatient treatment); 2: moderate severity (consider hospital admission); 3 or more: severe (consider ICU/HDU, IV antibiotics).', 2),
('e5000000-0000-0000-0000-000000000036', 'CURB-65 guides but does not replace overall clinical judgement regarding admission and treatment intensity.', 3),
('e5000000-0000-0000-0000-000000000037', 'Hospital-acquired pneumonia (HAP) is defined as pneumonia developing more than 48 hours after hospital admission and often involves different, sometimes more resistant, pathogens than community-acquired pneumonia.', 1),
('e5000000-0000-0000-0000-000000000037', 'Local antimicrobial guidelines for HAP should be followed, as they account for local resistance patterns and typically use broader-spectrum agents than for CAP.', 2),
('e5000000-0000-0000-0000-000000000037', 'Ventilator-associated pneumonia is a specific subtype of HAP occurring in intubated patients and may require even broader empirical cover.', 3),
('e5000000-0000-0000-0000-000000000038', $x$Dysphagia (e.g., from Parkinson's disease, stroke, or other neurological conditions) predisposes to aspiration pneumonia.$x$, 1),
('e5000000-0000-0000-0000-000000000038', 'Aspiration pneumonia classically affects dependent lung segments, commonly the right lower lobe, because of the more vertical, wider right main bronchus.', 2),
('e5000000-0000-0000-0000-000000000038', 'Management includes appropriate antibiotics (covering typical aspiration flora), speech and language therapy assessment for swallowing, and consideration of dietary modification to reduce recurrence risk.', 3),
('e5000000-0000-0000-0000-000000000039', 'Standard initial anti-tuberculous therapy is quadruple therapy (rifampicin, isoniazid, pyrazinamide, ethambutol) for 2 months, followed by rifampicin and isoniazid for a further 4 months in fully sensitive pulmonary TB.', 1),
('e5000000-0000-0000-0000-000000000039', 'Active pulmonary TB (particularly smear-positive) is notifiable to public health authorities and requires appropriate respiratory isolation precautions.', 2),
('e5000000-0000-0000-0000-000000000039', 'Key side effects to counsel on include hepatotoxicity (all four drugs, particularly isoniazid, rifampicin, and pyrazinamide), visual disturbance (ethambutol), and peripheral neuropathy (isoniazid, mitigated by pyridoxine).', 3),
('e5000000-0000-0000-0000-000000000040', 'Legionella pneumonia is associated with exposure to contaminated water systems (air conditioning, hot tubs, showers) and often causes extrapulmonary features: confusion, diarrhoea, hyponatraemia, and deranged liver function tests.', 1),
('e5000000-0000-0000-0000-000000000040', 'Legionella urinary antigen testing is a rapid, widely available diagnostic test.', 2),
('e5000000-0000-0000-0000-000000000040', 'Atypical pneumonia organisms (Legionella, Mycoplasma, Chlamydophila) are not covered by penicillins alone and require macrolide or tetracycline antibiotics.', 3),
('e5000000-0000-0000-0000-000000000041', 'Antiviral treatment (e.g., oseltamivir) is recommended for patients at high risk of influenza complications who present within 48 hours of symptom onset, even without current severe illness.', 1),
('e5000000-0000-0000-0000-000000000041', 'High-risk groups include older adults, pregnant women, and those with chronic conditions (diabetes, chronic kidney, heart, or lung disease, immunosuppression).', 2),
('e5000000-0000-0000-0000-000000000041', 'Secondary bacterial pneumonia is an important complication of influenza and should be considered if a patient deteriorates or fails to improve as expected.', 3),
('e5000000-0000-0000-0000-000000000042', 'Pneumocystis jirovecii pneumonia classically occurs in patients with CD4 counts below 200 cells/microL and presents with subacute progressive dyspnoea, dry cough, and exertional desaturation.', 1),
('e5000000-0000-0000-0000-000000000042', 'Chest X-ray typically shows bilateral perihilar or diffuse ground-glass infiltrates; chest X-ray can occasionally be normal despite significant hypoxia.', 2),
('e5000000-0000-0000-0000-000000000042', 'First-line treatment is high-dose co-trimoxazole; patients with a CD4 count below 200 should also be offered prophylaxis (co-trimoxazole) to prevent PJP going forward.', 3),
('e5000000-0000-0000-0000-000000000043', 'Obstructive sleep apnoea presents with loud snoring, witnessed apnoeic episodes, unrefreshing sleep, and excessive daytime sleepiness; risk factors include obesity, large neck circumference, and male sex.', 1),
('e5000000-0000-0000-0000-000000000043', 'Excessive daytime sleepiness with near-miss driving incidents raises an urgent road safety concern requiring prompt advice and action.', 2),
('e5000000-0000-0000-0000-000000000043', 'Screening tools such as STOP-BANG or the Epworth Sleepiness Scale can help assess pre-test probability of OSA prior to referral for sleep studies (polysomnography).', 3),
('e5000000-0000-0000-0000-000000000044', 'Excessive sleepiness due to obstructive sleep apnoea likely to impair driving is notifiable to the DVLA, and affected individuals must stop driving until symptoms are controlled.', 1),
('e5000000-0000-0000-0000-000000000044', 'Group 2 (HGV/bus) licence holders face stricter medical standards than Group 1 (car/motorcycle) licence holders and often require confirmed specialist assessment before resuming driving.', 2),
('e5000000-0000-0000-0000-000000000044', 'Clinicians have a duty to advise patients of their legal responsibility to inform the DVLA, and in exceptional circumstances where a patient continues driving against advice and poses a clear danger, may need to consider breaching confidentiality to notify the DVLA directly.', 3),
('e5000000-0000-0000-0000-000000000045', 'Obesity hypoventilation syndrome is defined by obesity (BMI 30 kg/m2 or more), daytime hypercapnia (PaCO2 above 6 kPa), and sleep-disordered breathing, after excluding other causes of hypoventilation.', 1),
('e5000000-0000-0000-0000-000000000045', 'It commonly coexists with obstructive sleep apnoea and can lead to pulmonary hypertension and right heart strain if untreated.', 2),
('e5000000-0000-0000-0000-000000000045', 'Management includes weight loss and non-invasive ventilation (e.g., CPAP or BiPAP), addressing both the sleep-disordered breathing and chronic hypoventilation.', 3),
('e5000000-0000-0000-0000-000000000046', 'NIV is indicated in COPD exacerbations with persistent respiratory acidosis (pH 7.25-7.35, elevated PaCO2) despite optimal initial medical management (controlled oxygen, bronchodilators, steroids, antibiotics).', 1),
('e5000000-0000-0000-0000-000000000046', 'NIV reduces work of breathing, improves alveolar ventilation, and has been shown to reduce mortality and the need for intubation in appropriate patients.', 2),
('e5000000-0000-0000-0000-000000000046', 'Invasive ventilation is considered when NIV fails, is contraindicated (e.g., facial trauma, vomiting, reduced consciousness with aspiration risk, or severe acidosis not responding), or is not tolerated.', 3),
('e5000000-0000-0000-0000-000000000047', 'Type 1 respiratory failure: PaO2 below 8 kPa with normal or low PaCO2, typically due to ventilation-perfusion mismatch (e.g., pneumonia, pulmonary oedema, PE, asthma).', 1),
('e5000000-0000-0000-0000-000000000047', 'Type 2 respiratory failure: PaO2 below 8 kPa with PaCO2 above 6 kPa, typically due to alveolar hypoventilation (e.g., COPD, neuromuscular disease, sedative overdose).', 2),
('e5000000-0000-0000-0000-000000000047', 'ABG interpretation should always assess oxygenation relative to inspired oxygen concentration (FiO2), as PaO2 targets and interpretation depend on the level of supplemental oxygen being delivered.', 3),
('e5000000-0000-0000-0000-000000000048', 'Patients with a history of hypercapnic respiratory failure (typically COPD) should have oxygen therapy titrated to a target saturation of 88-92%, using a documented prescription (e.g., an oxygen alert card).', 1),
('e5000000-0000-0000-0000-000000000048', 'Uncontrolled high-flow oxygen in these patients can suppress hypoxic respiratory drive and worsen ventilation-perfusion mismatch, precipitating dangerous hypercapnia.', 2),
('e5000000-0000-0000-0000-000000000048', 'Once blood gases confirm the patient is not a chronic CO2 retainer, the standard target range of 94-98% can be used.', 3),
('e5000000-0000-0000-0000-000000000049', 'CPAP is first-line treatment for moderate-to-severe symptomatic obstructive sleep apnoea, splinting the upper airway open during sleep to prevent apnoeic and hypopnoeic events.', 1),
('e5000000-0000-0000-0000-000000000049', 'Mandibular advancement devices and surgery are generally reserved for milder cases or CPAP intolerance/failure.', 2),
('e5000000-0000-0000-0000-000000000049', 'Lifestyle modification (weight loss, reduced alcohol, avoiding the supine sleep position) is an important adjunct but is usually insufficient alone in moderate-to-severe disease.', 3),
('e5000000-0000-0000-0000-000000000050', 'Central sleep apnoea with Cheyne-Stokes respiration is common in patients with heart failure with reduced ejection fraction, due to delayed feedback in the respiratory control system causing cyclical hyperventilation and central apnoea.', 1),
('e5000000-0000-0000-0000-000000000050', 'Unlike obstructive sleep apnoea, central sleep apnoea is not primarily driven by upper airway obstruction and is less strongly associated with obesity or loud snoring.', 2),
('e5000000-0000-0000-0000-000000000050', 'Management focuses on optimising treatment of the underlying heart failure; adaptive servo-ventilation has been associated with harm in certain heart failure populations and should only be used per specialist cardiology/sleep guidance.', 3);
